// Feature 4: ຟັງຊັນຄຳນວນ "1 ຂວດໃຊ້ກັບສັດໄດ້ຈັກໂຕ?" ແລະ "ໃຊ້ເຂັມເບີຫຍັງ?" ແບບພາສາຊາວບ້ານເຂົ້າໃຈງ່າຍ
function getPracticalDrugGuide(drug) {
    let coverage_lo = '';
    let coverage_th = '';
    let needle_lo = '';
    let needle_th = '';

    const isPoultryOnly = drug.species.length === 1 && drug.species[0] === 'poultry';
    const isExternal = drug.category === 'wound' || drug.id === 'm-moxide';

    if (isExternal) {
        if (drug.id === 'm-moxide') {
            coverage_lo = '1 ຂວດ (30cc) ຢອດຫຼັງງົວໄດ້ 3–5 ໂຕ ຫຼື ຢອດໄກ່ໄດ້ 150–300 ໂຕ';
            coverage_th = '1 ขวด (30cc) หยดหลังวัวได้ 3–5 ตัว หรือหยดไก่ได้ 150–300 ตัว';
        } else if (drug.id === 'bioclean') {
            coverage_lo = '1 ຂວດ (500cc) ປະສົມນ້ຳພົ່ນຄອກສັດໄດ້ 250–500 ລິດ';
            coverage_th = '1 ขวด (500cc) ผสมน้ำพ่นคอกสัตว์ได้ 250–500 ลิตร';
        } else {
            coverage_lo = 'ໃຊ້ພົ່ນ/ທາ/ຢອດ ບາດແຜພາຍນອກໄດ້ຫຼາຍສິບຄັ້ງ (ເກັບໄວ້ໃຊ້ຕໍ່ໄດ້ດົນ)';
            coverage_th = 'ใช้พ่น/ทา/หยอด ภายนอกได้หลายสิบครั้ง เก็บไว้ใช้ต่อได้นาน';
        }
        needle_lo = 'ບໍ່ຕ້ອງໃຊ້ເຂັມສັກຢາ (ຢາໃຊ້ພາຍນອກ)';
        needle_th = 'ไม่ต้องใช้เข็มฉีดยา (ยาใช้ภายนอก)';
    } else if (isPoultryOnly) {
        if (drug.calcRate > 0) {
            coverage_lo = 'ຂວດ 10cc ສັກໄກ່ໃຫຍ່/ໄກ່ຊົນໄດ້ປະມານ 20 ໂຕ (ໂຕລະ 0.5 cc)';
            coverage_th = 'ขวด 10cc ฉีดไก่ชน/ไก่ใหญ่ได้ประมาณ 20 ตัว (ตัวละ 0.5 cc)';
            needle_lo = 'ເຂັມເບີ 24G – 26G (ຍາວ 0.5 ນິ້ວ) ສັກກ້າມຊີ້ນໜ້າເອິກ';
            needle_th = 'เข็มเบอร์ 24G – 26G (ยาว 0.5 นิ้ว) ฉีดกล้ามเนื้อหน้าอก';
        } else {
            coverage_lo = 'ໃຊ້ປ້ອນ/ຢອດ ຕາມຂະໜາດບັນຈຸຂ້າງກ່ອງ (ກຽມໄວ້ປະຈຳຊຸ້ມໄກ່)';
            coverage_th = 'ใช้ป้อน/หยอด ตามขนาดบรรจุข้างกล่อง';
            needle_lo = 'ຢາກິນ/ຢາຢອດ (ບໍ່ຕ້ອງໃຊ້ເຂັມສັກ)';
            needle_th = 'ยากิน/ยาหยอด (ไม่ต้องใช้เข็มฉีด)';
        }
    } else if (drug.id === 'albendazole-oral') {
        coverage_lo = 'ຢາກອກປາກ: 100cc ກອກງົວໃຫຍ່ໄດ້ 3–4 ໂຕ ຫຼື ແບ້/ລູກງົວ ໄດ້ 15–25 ໂຕ';
        coverage_th = 'ยากรอกปาก: 100cc กรอกวัวใหญ่ได้ 3–4 ตัว หรือแพะ/ลูกวัว 15–25 ตัว';
        needle_lo = 'ໃຊ້ໄຊຣິງຄ໌ດູດກອກທາງປາກ (ຫ້າມໃຊ້ເຂັມສັກ!)';
        needle_th = 'ใช้ไซริงค์ดูดกรอกทางปาก (ห้ามฉีด!)';
    } else if (drug.id === 'ivermec-f' || drug.id === 'vimec-ivermectin') {
        coverage_lo = 'ປະຢັດຫຼາຍ: ຂວດ 50cc ສັກງົວໃຫຍ່ໄດ້ ~10 ໂຕ | ຂວດ 100cc ສັກງົວໄດ້ ~20 ໂຕ (ຫຼື ໝູ/ແບ້ 50–100 ໂຕ)';
        coverage_th = 'ประหยัดมาก: ขวด 50cc ฉีดวัวใหญ่ได้ ~10 ตัว | ขวด 100cc ฉีดวัวได้ ~20 ตัว';
        needle_lo = 'ເຂັມເບີ 18G–20G (ສັ້ນ 0.5–1 ນິ້ວ) ສັກດຶງໜັງຄໍ SC ເທົ່ານັ້ນ';
        needle_th = 'เข็มเบอร์ 18G–20G ฉีดเข้าใต้ผิวหนัง (SC) เท่านั้น';
    } else {
        coverage_lo = 'ຂວດ 100cc ສັກງົວ/ຄວາຍໃຫຍ່ໄດ້ປະມານ 5–8 ໂຕ (ຫຼື ໝູ/ແບ້ ໄດ້ 15–30 ໂຕ)';
        coverage_th = 'ขวด 100cc ฉีดวัว/ควายใหญ่ได้ประมาณ 5–8 ตัว (หรือหมู/แพะ 15–30 ตัว)';
        needle_lo = 'ງົວ/ຄວາຍ: ເຂັມ 16G–18G | ໝູ/ແບ້: ເຂັມ 18G–20G | ໄກ່: ເຂັມ 24G–26G';
        needle_th = 'วัว/ควาย: เข็ม 16G–18G | หมู/แพะ: เข็ม 18G–20G | ไก่: เข็ม 24G–26G';
    }

    return {
        coverage: currentLang === 'lo' ? coverage_lo : coverage_th,
        needle: currentLang === 'lo' ? needle_lo : needle_th
    };
}

// ==========================================
// 6. ຟັງຊັນເຊື່ອມຕໍ່ WhatsApp ໂດຍກົງ (DIRECT WHATSAPP HELPERS)
// ==========================================
function openWhatsAppCustom(messageText) {
    const encoded = encodeURIComponent(messageText);
    window.open(`https://wa.me/${SHOP_WHATSAPP}?text=${encoded}`, '_blank');
}

function openGeneralWhatsApp() {
    const msg = currentLang === 'lo'
        ? 'ສະບາຍດີຮ້ານຂາຍຢາສັດ, ຂ້ອຍເບິ່ງຂໍ້ມູນຢູ່ເວັບໄຊ ຕ້ອງການສອບຖາມຂໍ້ມູນ ແລະ ສັ່ງຊື້ຢາສັດແດ່ເດີ້'
        : 'สวัสดีครับ/ค่ะ สนใจสอบถามข้อมูลและสั่งซื้อยาสัตว์จากหน้าเว็บไซต์ครับ';
    openWhatsAppCustom(msg);
}

function openConsultWhatsApp(diseaseTitle) {
    let msg = '';
    if (diseaseTitle) {
        msg = currentLang === 'lo'
            ? `ສະບາຍດີຮ້ານຂາຍຢາສັດ, ສັດລ້ຽງຂອງຂ້ອຍມີອາການຄ້າຍຄື "${diseaseTitle}" ຂໍປຶກສາວິທີປິ່ນປົວ ແລະ ຢາທີ່ຄວນໃຊ້ແດ່ເດີ້`
            : `สวัสดีครับ สัตว์เลี้ยงของผมมีอาการคล้าย "${diseaseTitle}" ขอปรึกษาแนวทางรักษาและยาที่ใช้หน่อยครับ`;
    } else {
        msg = currentLang === 'lo'
            ? 'ສະບາຍດີຮ້ານຂາຍຢາສັດ, ຂ້ອຍຕ້ອງການປຶກສາອາການສັດປ່ວຍ (ດຽວຂ້ອຍສົ່ງຮູບ/ອາການໃຫ້ເບິ່ງເດີ້) ຂໍຄຳແນະນຳຈັດຢາໃຫ້ແດ່'
            : 'สวัสดีครับ ต้องการปรึกษาอาการสัตว์ป่วย (เดี๋ยวส่งรูป/อาการให้ดูครับ) รบกวนแนะนำยาให้หน่อยครับ';
    }
    openWhatsAppCustom(msg);
}

function openWhatsAppDrug(drugId) {
    const drug = DRUGS_DATA.find(d => d.id === drugId);
    if (!drug) return;

    let sizePriceText = '';
    if (drug.sizes && drug.sizes.length > 0) {
        const idx = selectedSizes[drug.id] || 0;
        const chosen = drug.sizes[idx] || drug.sizes[0];
        sizePriceText = ` (ຂະໜາດ ${chosen.size} - ລາຄາ ${chosen.price})`;
    }

    const msg = currentLang === 'lo'
        ? `ສະບາຍດີຮ້ານຂາຍຢາສັດ, ຂ້ອຍສົນໃຈສິນຄ້າ: "${drug.name}"${sizePriceText} ມີສິນຄ້າພ້ອມສົ່ງບໍ່? ຂໍລາຍລະອຽດແດ່ເດີ້`
        : `สวัสดีครับ สนใจสั่งซื้อยา: "${drug.name}"${sizePriceText} มีสินค้าพร้อมส่งไหมครับ?`;
    openWhatsAppCustom(msg);
}

function openWhatsAppBundle(bundleId) {
    const b = BUNDLES_DATA.find(item => item.id === bundleId);
    if (!b) return;
    const title = currentLang === 'lo' ? b.title_lo : b.title_th;
    const msg = currentLang === 'lo'
        ? `ສະບາຍດີຮ້ານຂາຍຢາສັດ, ຂ້ອຍສົນໃຈສັ່ງຊື້ "${title}" (${b.totalPrice}) ພ້ອມເຂັມສັກຢາ ຂໍລາຍລະອຽດການສົ່ງແດ່ເດີ້`
        : `สวัสดีครับ สนใจสั่งซื้อ "${title}" (${b.totalPrice}) พร้อมเข็มฉีดยา ขอรายละเอียดการจัดส่งหน่อยครับ`;
    openWhatsAppCustom(msg);
}

function selectDrugSize(drugId, sizeIdx) {
    selectedSizes[drugId] = sizeIdx;
    renderDrugGrid();
}

// ==========================================
// 7. ຟັງຊັນເລີ່ມຕົ້ນລະບົບ (INITIALIZATION)
// ==========================================
document.addEventListener('DOMContentLoaded', () => {
    const statCountEl = document.getElementById('stat-drug-count');
    if (statCountEl) statCountEl.innerText = DRUGS_DATA.length;

    loadCartFromStorage();
    setLanguage('lo');
    populateCalculatorDropdown();

    // Search and filters
    document.getElementById('search-input').addEventListener('input', (e) => {
        currentSearch = e.target.value.toLowerCase().trim();
        updateQuickPillState();
        renderDrugGrid();
    });

    document.getElementById('disease-search-input').addEventListener('input', (e) => {
        currentDiseaseSearch = e.target.value.toLowerCase().trim();
        renderDiseaseGrid();
    });

    document.getElementById('category-filter').addEventListener('change', (e) => {
        currentCategory = e.target.value;
        updateQuickPillState();
        renderDrugGrid();
    });

    document.getElementById('animal-filter').addEventListener('change', (e) => {
        currentAnimal = e.target.value;
        updateQuickPillState();
        renderDrugGrid();
    });

    // Quick Filter Pills
    document.querySelectorAll('.quick-pill').forEach(btn => {
        btn.addEventListener('click', () => {
            const filter = btn.getAttribute('data-quick');
            if (currentQuickFilter === filter) {
                currentQuickFilter = null;
            } else {
                currentQuickFilter = filter;
            }
            updateQuickPillState();
            renderDrugGrid();
        });
    });

    document.getElementById('clear-filters-btn').addEventListener('click', () => {
        currentSearch = '';
        currentCategory = 'all';
        currentAnimal = 'all';
        currentQuickFilter = null;
        currentSymptomFilter = null;
        document.getElementById('search-input').value = '';
        document.getElementById('category-filter').value = 'all';
        document.getElementById('animal-filter').value = 'all';
        renderSymptomBar();
        updateQuickPillState();
        renderDrugGrid();
    });

    // Language toggles
    document.getElementById('lang-lo').addEventListener('click', () => setLanguage('lo'));
    document.getElementById('lang-th').addEventListener('click', () => setLanguage('th'));

    // Modals toggle
    document.getElementById('calc-toggle-btn').addEventListener('click', () => openCalculator());
    document.getElementById('calc-close-btn').addEventListener('click', () => closeCalculator());
    document.getElementById('calc-done-btn').addEventListener('click', () => closeCalculator());

    document.getElementById('detail-close-btn').addEventListener('click', () => closeDetailModal());
    document.getElementById('detail-drawer-close').addEventListener('click', () => closeDetailModal());

    // Close modals on backdrop click
    document.getElementById('detail-modal').addEventListener('click', (e) => {
        if (e.target.id === 'detail-modal') closeDetailModal();
    });
    document.getElementById('calc-modal').addEventListener('click', (e) => {
        if (e.target.id === 'calc-modal') closeCalculator();
    });

    // Calculator inputs
    document.getElementById('calc-drug-select').addEventListener('change', calculateDosage);
    document.getElementById('calc-weight').addEventListener('input', calculateDosage);
    document.getElementById('calc-species').addEventListener('change', calculateDosage);

    document.getElementById('detail-use-calc-btn').addEventListener('click', () => {
        const drugId = document.getElementById('detail-modal').dataset.activeDrugId;
        closeDetailModal();
        openCalculator(drugId);
    });

    const detailWaBtn = document.getElementById('detail-wa-btn');
    if (detailWaBtn) {
        detailWaBtn.addEventListener('click', () => {
            const drugId = document.getElementById('detail-modal').dataset.activeDrugId;
            openWhatsAppDrug(drugId);
        });
    }
});

function setLanguage(lang) {
    currentLang = lang;
    const totalDrugs = DRUGS_DATA.length;
    const totalDiseases = DISEASES_DATA.length;
    if (lang === 'lo') {
        document.getElementById('lang-lo').className = "px-2 sm:px-2.5 py-1 sm:py-1.5 rounded-lg bg-white text-slate-900 shadow-sm transition";
        document.getElementById('lang-th').className = "px-2 sm:px-2.5 py-1 sm:py-1.5 rounded-lg text-slate-600 hover:text-slate-900 transition";
        document.getElementById('tab-drugs-label').innerText = `ຄັງຢາສັດ (${totalDrugs})`;
        document.getElementById('tab-bundles-label').innerText = "ຊຸດຢາຈັດເຊັດ (6 ຊຸດ)";
        document.getElementById('tab-diseases-label').innerText = `ວິນິດໄສ ${totalDiseases} ໂຣກ`;
        document.getElementById('tab-faq-label').innerText = "ວັກຊີນ, ເບີເຂັມ & FAQ";
    } else {
        document.getElementById('lang-th').className = "px-2 sm:px-2.5 py-1 sm:py-1.5 rounded-lg bg-white text-slate-900 shadow-sm transition";
        document.getElementById('lang-lo').className = "px-2 sm:px-2.5 py-1 sm:py-1.5 rounded-lg text-slate-600 hover:text-slate-900 transition";
        document.getElementById('tab-drugs-label').innerText = `คลังยาสัตว์ (${totalDrugs})`;
        document.getElementById('tab-bundles-label').innerText = "ชุดยาจัดเซ็ต (6 ชุด)";
        document.getElementById('tab-diseases-label').innerText = `วินิจฉัย ${totalDiseases} โรค`;
        document.getElementById('tab-faq-label').innerText = "วัคซีน, เบอร์เข็ม & FAQ";
    }
    renderSymptomBar();
    renderDrugGrid();
    renderBundlesGrid();
    renderPoultrySymptomChecker();
    renderDiseaseGrid();
    renderFaqGrid();
    calculateDosage();
}

function setMobileGridCols(cols) {
    mobileGridCols = cols;
    const grid = document.getElementById('drug-grid');
    const btn2 = document.getElementById('mobile-col-2');
    const btn1 = document.getElementById('mobile-col-1');
    if (!grid) return;

    if (cols === 1) {
        grid.className = "grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3 sm:gap-5";
        if (btn1) btn1.className = "px-2 py-1 rounded-md text-[11px] font-bold bg-teal-600 text-white shadow-sm transition";
        if (btn2) btn2.className = "px-2 py-1 rounded-md text-[11px] font-bold text-slate-500 hover:text-slate-800 transition";
    } else {
        grid.className = "grid grid-cols-2 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-2.5 sm:gap-5";
        if (btn2) btn2.className = "px-2 py-1 rounded-md text-[11px] font-bold bg-teal-600 text-white shadow-sm transition";
        if (btn1) btn1.className = "px-2 py-1 rounded-md text-[11px] font-bold text-slate-500 hover:text-slate-800 transition";
    }
    renderDrugGrid();
}

function switchMainTab(tab) {
    currentMainTab = tab;
    const views = {
        drugs: document.getElementById('view-drugs'),
        bundles: document.getElementById('view-bundles'),
        diseases: document.getElementById('view-diseases'),
        faq: document.getElementById('view-faq')
    };
    const btns = {
        drugs: document.getElementById('tab-drugs-btn'),
        bundles: document.getElementById('tab-bundles-btn'),
        diseases: document.getElementById('tab-diseases-btn'),
        faq: document.getElementById('tab-faq-btn')
    };
    const mBtns = {
        drugs: document.getElementById('mnav-drugs'),
        bundles: document.getElementById('mnav-bundles'),
        diseases: document.getElementById('mnav-diseases')
    };

    const activeClass = "shrink-0 inline-flex items-center gap-1.5 sm:gap-2 px-3 sm:px-3.5 py-2 sm:py-2.5 rounded-xl text-xs sm:text-sm font-bold bg-white text-teal-700 shadow-sm transition";
    const inactiveClass = "shrink-0 inline-flex items-center gap-1.5 sm:gap-2 px-3 sm:px-3.5 py-2 sm:py-2.5 rounded-xl text-xs sm:text-sm font-bold text-slate-600 hover:text-slate-900 transition";

    const mActiveClass = "flex flex-col items-center justify-center py-2 text-teal-700 font-bold text-[10px] gap-0.5 bg-teal-50/60";
    const mInactiveClass = "flex flex-col items-center justify-center py-2 text-slate-500 hover:text-teal-700 font-semibold text-[10px] gap-0.5";

    Object.keys(views).forEach(k => {
        if (views[k]) views[k].classList.add('hidden');
        if (btns[k]) btns[k].className = inactiveClass;
        if (mBtns[k]) mBtns[k].className = mInactiveClass;
    });

    if (views[tab]) views[tab].classList.remove('hidden');
    if (btns[tab]) btns[tab].className = activeClass;
    if (mBtns[tab]) mBtns[tab].className = mActiveClass;
}

// Feature 1: Render Symptom Quick-Finder Bar
function renderSymptomBar() {
    const container = document.getElementById('symptom-pills-container');
    const adviceBox = document.getElementById('symptom-advice-box');
    if (!container) return;
    container.innerHTML = '';

    SYMPTOM_FILTERS.forEach(sym => {
        const isActive = currentSymptomFilter === sym.id;
        const btn = document.createElement('button');
        btn.className = isActive
            ? "whitespace-nowrap px-2.5 sm:px-3 py-1.5 rounded-xl text-[11px] sm:text-xs font-extrabold bg-teal-700 text-white shadow-sm ring-2 ring-teal-500 transition flex items-center gap-1"
            : "whitespace-nowrap px-2.5 sm:px-3 py-1.5 rounded-xl text-[11px] sm:text-xs font-semibold bg-white hover:bg-teal-50 text-slate-700 border border-slate-200/90 shadow-sm transition flex items-center gap-1";
        btn.innerHTML = `<span>${currentLang === 'lo' ? sym.label_lo : sym.label_th}</span>`;
        btn.addEventListener('click', () => {
            if (currentSymptomFilter === sym.id) {
                currentSymptomFilter = null;
            } else {
                currentSymptomFilter = sym.id;
            }
            renderSymptomBar();
            updateQuickPillState();
            renderDrugGrid();
        });
        container.appendChild(btn);
    });

    if (currentSymptomFilter) {
        const activeSym = SYMPTOM_FILTERS.find(s => s.id === currentSymptomFilter);
        if (activeSym && adviceBox) {
            const label = currentLang === 'lo' ? activeSym.label_lo : activeSym.label_th;
            const advice = currentLang === 'lo' ? activeSym.advice_lo : activeSym.advice_th;
            document.getElementById('symptom-advice-title').innerText = `💡 ຄຳແນະນຳສຳລັບອາການ: ${label}`;
            document.getElementById('symptom-advice-desc').innerText = advice;
            const waBtn = document.getElementById('symptom-wa-btn');
            waBtn.onclick = () => openConsultWhatsApp(label);
            adviceBox.classList.remove('hidden');
        }
    } else if (adviceBox) {
        adviceBox.classList.add('hidden');
    }
}

// Feature 2: Render Complete Treatment Bundles Grid
function renderBundlesGrid() {
    const grid = document.getElementById('bundle-grid');
    if (!grid) return;
    grid.innerHTML = '';

    BUNDLES_DATA.forEach(b => {
        const card = document.createElement('div');
        card.className = "bg-white rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition p-5 flex flex-col justify-between";

        const badge = currentLang === 'lo' ? b.badge_lo : b.badge_th;
        const title = currentLang === 'lo' ? b.title_lo : b.title_th;
        const target = currentLang === 'lo' ? b.target_lo : b.target_th;
        const needle = currentLang === 'lo' ? b.needle_lo : b.needle_th;

        const itemsHtml = b.items.map(item => {
            const drugObj = DRUGS_DATA.find(d => d.id === item.drugId);
            const thumb = (drugObj && drugObj.image)
                ? `<img src="${drugObj.image}" class="w-9 h-9 rounded-lg object-contain bg-white border border-slate-200 shrink-0">`
                : `<div class="w-9 h-9 rounded-lg bg-teal-50 text-teal-700 flex items-center justify-center text-xs shrink-0"><i class="fa-solid fa-prescription-bottle-medical"></i></div>`;
            return `
                <div onclick="openDetailModal('${item.drugId}')" class="cursor-pointer flex items-center justify-between gap-2 p-2 rounded-xl bg-slate-50 hover:bg-teal-50/60 border border-slate-100 transition">
                    <div class="flex items-center gap-2.5 min-w-0">
                        ${thumb}
                        <span class="text-xs font-semibold text-slate-800 truncate">${item.note_lo}</span>
                    </div>
                    <span class="text-[11px] font-bold text-teal-700 shrink-0">${item.price}</span>
                </div>
            `;
        }).join('');

        card.innerHTML = `
            <div class="space-y-3.5">
                <div>
                    <span class="inline-block px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-amber-50 text-amber-800 border border-amber-200 mb-1.5">${badge}</span>
                    <h3 class="font-extrabold text-slate-900 text-base leading-snug">${title}</h3>
                    <p class="text-xs text-slate-600 mt-1 leading-relaxed">${target}</p>
                </div>

                <div class="space-y-1.5">
                    <div class="text-[11px] font-bold text-slate-400 uppercase tracking-wider">ຢາທີ່ຈັດຢູ່ໃນຊຸດນີ້ (ກົດເບິ່ງລາຍລະອຽດແຕ່ລະຂວດໄດ້):</div>
                    ${itemsHtml}
                </div>

                <div class="p-2.5 rounded-xl bg-sky-50/80 border border-sky-100 text-[11px] text-sky-900 flex items-start gap-2">
                    <i class="fa-solid fa-syringe text-sky-600 mt-0.5"></i>
                    <span><strong>ອຸປະກອນສັກ:</strong> ${needle}</span>
                </div>
            </div>

            <div class="mt-4 pt-3.5 border-t border-slate-100 space-y-2">
                <div class="flex items-center justify-between">
                    <span class="text-xs font-semibold text-slate-500">ລາຄາປະມານການຍົກຊຸດ:</span>
                    <span class="text-base font-extrabold text-rose-600">${b.totalPrice}</span>
                </div>
                <button onclick="openWhatsAppBundle('${b.id}')" class="w-full py-2.5 px-4 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-extrabold flex items-center justify-center gap-2 shadow-sm transition">
                    <i class="fa-brands fa-whatsapp text-base"></i>
                    <span>ສົນໃຈຊຸດນີ້ ທັກ WhatsApp</span>
                </button>
            </div>
        `;

        grid.appendChild(card);
    });
}

function renderFaqGrid() {
    const grid = document.getElementById('faq-grid');
    if (!grid) return;
    grid.innerHTML = '';

    FAQ_DATA.forEach(item => {
        const div = document.createElement('div');
        div.className = "bg-white rounded-2xl border border-slate-200 p-5 shadow-sm space-y-2";
        const q = currentLang === 'lo' ? item.q_lo : item.q_th;
        const a = currentLang === 'lo' ? item.a_lo : item.a_th;

        div.innerHTML = `
            <h4 class="font-bold text-slate-900 text-xs sm:text-sm flex items-start gap-2">
                <i class="fa-solid fa-circle-question text-teal-600 mt-0.5 shrink-0"></i>
                <span>${q}</span>
            </h4>
            <p class="text-xs text-slate-600 leading-relaxed pl-6">${a}</p>
        `;
        grid.appendChild(div);
    });
}

function setDiseaseSpeciesFilter(species) {
    currentDiseaseSpecies = species;
    document.querySelectorAll('.dspecies-btn').forEach(btn => {
        if (btn.getAttribute('data-dspecies') === species) {
            btn.className = "dspecies-btn px-3 py-1.5 rounded-xl text-xs font-bold bg-white text-teal-800 shadow-sm transition";
        } else {
            btn.className = "dspecies-btn px-3 py-1.5 rounded-xl text-xs font-semibold bg-white/15 hover:bg-white/25 text-white transition";
        }
    });

    const poultryPanel = document.getElementById('poultry-subfilter-panel');
    if (species === 'cattle' || species === 'goat' || species === 'pig') {
        currentPoultryCategory = 'all';
        selectedPoultrySymptoms.clear();
        updatePoultryCategoryButtons();
        renderPoultrySymptomChecker();
        if (poultryPanel) poultryPanel.classList.add('hidden');
    } else {
        if (poultryPanel) poultryPanel.classList.remove('hidden');
    }

    renderDiseaseGrid();
}

function updatePoultryCategoryButtons() {
    document.querySelectorAll('.pcat-btn').forEach(btn => {
        const cat = btn.getAttribute('data-pcat');
        if (cat === currentPoultryCategory) {
            btn.className = "pcat-btn px-3 py-1.5 rounded-xl text-xs font-bold bg-amber-600 text-white shadow-sm transition";
        } else {
            btn.className = "pcat-btn px-3 py-1.5 rounded-xl text-xs font-semibold bg-white hover:bg-amber-50 text-slate-700 border border-amber-200 transition";
        }
    });
}

function setPoultryCategoryFilter(cat) {
    currentPoultryCategory = cat;
    updatePoultryCategoryButtons();

    // ຖ້າເລືອກໝວດພະຍາດໄກ່ ໃຫ້ປັບໂໝດສັດເປັນ ສັດປີກ ຫຼື ທັງໝົດ ໂດຍອັດຕະໂນມັດ
    if (cat !== 'all' && currentDiseaseSpecies !== 'poultry') {
        currentDiseaseSpecies = 'poultry';
        document.querySelectorAll('.dspecies-btn').forEach(btn => {
            if (btn.getAttribute('data-dspecies') === 'poultry') {
                btn.className = "dspecies-btn px-3 py-1.5 rounded-xl text-xs font-bold bg-white text-teal-800 shadow-sm transition";
            } else {
                btn.className = "dspecies-btn px-3 py-1.5 rounded-xl text-xs font-semibold bg-white/15 hover:bg-white/25 text-white transition";
            }
        });
    }
    renderDiseaseGrid();
}

function togglePoultryChecker() {
    const box = document.getElementById('poultry-symptom-checker-box');
    const icon = document.getElementById('poultry-checker-icon');
    if (!box) return;
    if (box.classList.contains('hidden')) {
        box.classList.remove('hidden');
        if (icon) icon.className = "fa-solid fa-chevron-up text-[10px]";
        renderPoultrySymptomChecker();
    } else {
        box.classList.add('hidden');
        if (icon) icon.className = "fa-solid fa-chevron-down text-[10px]";
    }
}

function renderPoultrySymptomChecker() {
    const grid = document.getElementById('poultry-symptom-groups-grid');
    const clearBtn = document.getElementById('clear-poultry-sym-btn');
    const summaryEl = document.getElementById('poultry-symptom-match-summary');
    if (!grid) return;
    grid.innerHTML = '';

    POULTRY_SYMPTOM_GROUPS.forEach(group => {
        const col = document.createElement('div');
        col.className = "bg-slate-50/90 rounded-xl p-3 border border-slate-200/80 space-y-2";
        const gTitle = currentLang === 'lo' ? group.group_lo : group.group_th;

        const buttonsHtml = group.items.map(item => {
            const isSelected = selectedPoultrySymptoms.has(item.id);
            const label = currentLang === 'lo' ? item.label_lo : item.label_th;
            const btnClass = isSelected
                ? "w-full text-left px-2.5 py-1.5 rounded-lg text-[11px] font-bold bg-amber-600 text-white shadow-sm flex items-center justify-between gap-1.5 transition"
                : "w-full text-left px-2.5 py-1.5 rounded-lg text-[11px] font-medium bg-white hover:bg-amber-50 text-slate-700 border border-slate-200/90 flex items-center justify-between gap-1.5 transition";
            const checkIcon = isSelected
                ? `<i class="fa-solid fa-circle-check text-white shrink-0"></i>`
                : `<i class="fa-regular fa-circle text-slate-300 shrink-0"></i>`;
            return `
                <button onclick="togglePoultrySymptom('${item.id}')" class="${btnClass}">
                    <span class="leading-snug">${label}</span>
                    ${checkIcon}
                </button>
            `;
        }).join('');

        col.innerHTML = `
            <div class="text-xs font-extrabold text-amber-950 border-b border-amber-200/60 pb-1.5">${gTitle}</div>
            <div class="space-y-1.5">${buttonsHtml}</div>
        `;
        grid.appendChild(col);
    });

    if (selectedPoultrySymptoms.size > 0) {
        if (clearBtn) clearBtn.classList.remove('hidden');
        if (summaryEl) {
            summaryEl.innerText = currentLang === 'lo'
                ? `🎯 ກຳລັງວິເຄາະຈາກອາການໄກ່ປ່ວຍທີ່ເລືອກ ${selectedPoultrySymptoms.size} ອາການ (ລຽງຕາມໂຣກທີ່ກົງທີ່ສຸດກ່ອນ)`
                : `🎯 กำลังวิเคราะห์จากอาการไก่ป่วยที่เลือก ${selectedPoultrySymptoms.size} อาการ (เรียงตามโรคที่ตรงที่สุด)`;
        }
    } else {
        if (clearBtn) clearBtn.classList.add('hidden');
        if (summaryEl) summaryEl.innerText = '';
    }
}

function togglePoultrySymptom(symId) {
    if (selectedPoultrySymptoms.has(symId)) {
        selectedPoultrySymptoms.delete(symId);
    } else {
        selectedPoultrySymptoms.add(symId);
    }
    if (selectedPoultrySymptoms.size > 0 && currentDiseaseSpecies !== 'poultry' && currentDiseaseSpecies !== 'all') {
        currentDiseaseSpecies = 'poultry';
        document.querySelectorAll('.dspecies-btn').forEach(btn => {
            if (btn.getAttribute('data-dspecies') === 'poultry') {
                btn.className = "dspecies-btn px-3 py-1.5 rounded-xl text-xs font-bold bg-white text-teal-800 shadow-sm transition";
            } else {
                btn.className = "dspecies-btn px-3 py-1.5 rounded-xl text-xs font-semibold bg-white/15 hover:bg-white/25 text-white transition";
            }
        });
    }
    renderPoultrySymptomChecker();
    renderDiseaseGrid();
}

function clearPoultrySymptoms() {
    selectedPoultrySymptoms.clear();
    renderPoultrySymptomChecker();
    renderDiseaseGrid();
}

function renderDiseaseGrid() {
    const grid = document.getElementById('disease-grid');
    const emptyState = document.getElementById('disease-empty-state');
    if (!grid) return;
    grid.innerHTML = '';

    // ອັບເດດຈຳນວນໂຣກທັງໝົດ ແລະ ໂຣກສັດປີກ
    const dcountAll = document.getElementById('dcount-all');
    const dcountPoultry = document.getElementById('dcount-poultry');
    if (dcountAll) dcountAll.innerText = DISEASES_DATA.length;
    if (dcountPoultry) dcountPoultry.innerText = DISEASES_DATA.filter(d => d.species.includes('poultry')).length;

    let filtered = DISEASES_DATA.filter(d => {
        const matchSpecies = currentDiseaseSpecies === 'all' || d.species.includes(currentDiseaseSpecies);
        const matchPoultryCat = currentPoultryCategory === 'all' || d.poultryCategory === currentPoultryCategory;
        const matchPoultrySym = selectedPoultrySymptoms.size === 0 ||
            (Array.isArray(d.symptomKeys) && d.symptomKeys.some(k => selectedPoultrySymptoms.has(k)));
        const matchSearch = currentDiseaseSearch === '' ||
            d.name_lo.toLowerCase().includes(currentDiseaseSearch) ||
            d.name_th.toLowerCase().includes(currentDiseaseSearch) ||
            d.cause.toLowerCase().includes(currentDiseaseSearch) ||
            d.symptoms_lo.some(s => s.toLowerCase().includes(currentDiseaseSearch)) ||
            d.symptoms_th.some(s => s.toLowerCase().includes(currentDiseaseSearch)) ||
            d.treatment_lo.some(t => t.toLowerCase().includes(currentDiseaseSearch));

        return matchSpecies && matchPoultryCat && matchPoultrySym && matchSearch;
    });

    // ຖ້າມີການເລືອກອາການໄກ່ປ່ວຍ ໃຫ້ລຽງລຳດັບໂຣກທີ່ກົງຫຼາຍຂໍ້ທີ່ສຸດຂຶ້ນກ່ອນ
    if (selectedPoultrySymptoms.size > 0) {
        filtered.sort((a, b) => {
            const countA = Array.isArray(a.symptomKeys) ? a.symptomKeys.filter(k => selectedPoultrySymptoms.has(k)).length : 0;
            const countB = Array.isArray(b.symptomKeys) ? b.symptomKeys.filter(k => selectedPoultrySymptoms.has(k)).length : 0;
            return countB - countA;
        });
    }

    if (filtered.length === 0) {
        emptyState.classList.remove('hidden');
        return;
    } else {
        emptyState.classList.add('hidden');
    }

    filtered.forEach(d => {
        const card = document.createElement('div');
        card.className = "bg-white rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition p-5 flex flex-col justify-between";

        const title = currentLang === 'lo' ? d.name_lo : d.name_th;
        const speciesLabel = currentLang === 'lo' ? d.speciesLabel_lo : d.speciesLabel_th;
        const symptoms = currentLang === 'lo' ? d.symptoms_lo : d.symptoms_th;
        const treatments = currentLang === 'lo' ? d.treatment_lo : d.treatment_th;

        let sevBadge = '';
        if (d.severity === 'critical') {
            sevBadge = `<span class="px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-rose-50 text-rose-700 border border-rose-200 shrink-0">${currentLang === 'lo' ? 'ສຸກເສີນ / ຕາຍໄວ' : 'ฉุกเฉิน / รุนแรง'}</span>`;
        } else if (d.severity === 'high') {
            sevBadge = `<span class="px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-amber-50 text-amber-700 border border-amber-200 shrink-0">${currentLang === 'lo' ? 'ພົບເລື້ອຍ / ຮຸນແຮງ' : 'พบบ่อย / รุนแรง'}</span>`;
        } else {
            sevBadge = `<span class="px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-teal-50 text-teal-700 border border-teal-200 shrink-0">${currentLang === 'lo' ? 'ໂຣກຊ້ຳເຮື້ອ / ບຳລຸງ' : 'เรื้อรัง / บำรุง'}</span>`;
        }

        // ປ້າຍໝວດໝູ່ພະຍາດສັດປີກ (5 ກຸ່ມຫຼັກ)
        let poultryCatBadge = '';
        if (d.poultryCategoryLabel_lo || d.poultryCategoryLabel_th) {
            const pLabel = currentLang === 'lo' ? d.poultryCategoryLabel_lo : d.poultryCategoryLabel_th;
            poultryCatBadge = `<span class="px-2 py-0.5 rounded-md text-[10px] font-bold bg-amber-100/90 text-amber-900 border border-amber-200">${pLabel}</span>`;
        }

        // ປ້າຍຈຳນວນອາການທີ່ກົງກັບການກວດເຊັກ
        let symptomMatchBadge = '';
        if (selectedPoultrySymptoms.size > 0 && Array.isArray(d.symptomKeys)) {
            const matchedCount = d.symptomKeys.filter(k => selectedPoultrySymptoms.has(k)).length;
            if (matchedCount > 0) {
                symptomMatchBadge = `<span class="px-2 py-0.5 rounded-md text-[10px] font-extrabold bg-emerald-600 text-white shadow-sm">🎯 ${currentLang === 'lo' ? `ກົງ ${matchedCount}/${selectedPoultrySymptoms.size} ອາການ` : `ตรง ${matchedCount}/${selectedPoultrySymptoms.size} อาการ`}</span>`;
            }
        }

        const drugButtonsHtml = d.recommendedDrugs.map(drugId => {
            const drugObj = DRUGS_DATA.find(item => item.id === drugId);
            if (!drugObj) return '';
            return `
                <button onclick="openDetailModal('${drugObj.id}')" class="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg bg-teal-50 hover:bg-teal-600 text-teal-800 hover:text-white border border-teal-200 text-xs font-semibold transition">
                    <i class="${drugObj.icon} text-[11px]"></i>
                    <span>${drugObj.name}</span>
                </button>
            `;
        }).join('');

        const safeTitle = title.replace(/'/g, "\\'");

        card.innerHTML = `
            <div class="space-y-4">
                <div class="flex items-start justify-between gap-2 border-b border-slate-100 pb-3">
                    <div>
                        <div class="flex flex-wrap items-center gap-1.5 text-xs font-semibold text-teal-700 mb-1">
                            <span class="inline-flex items-center gap-1"><i class="fa-solid fa-paw"></i> ${speciesLabel}</span>
                            ${poultryCatBadge}
                            ${symptomMatchBadge}
                        </div>
                        <h3 class="font-bold text-slate-900 text-base leading-snug">${title}</h3>
                        <p class="text-[11px] text-slate-400 mt-0.5">${d.cause}</p>
                    </div>
                    ${sevBadge}
                </div>

                <div>
                    <h4 class="text-xs font-bold text-slate-700 mb-1.5 flex items-center gap-1.5">
                        <i class="fa-solid fa-magnifying-glass-plus text-rose-500"></i>
                        <span>${currentLang === 'lo' ? 'ອາການສັງເກດສຳຄັນ:' : 'อาการสำคัญ:'}</span>
                    </h4>
                    <ul class="text-xs text-slate-600 space-y-1 list-disc list-inside leading-relaxed bg-slate-50 p-3 rounded-xl border border-slate-100">
                        ${symptoms.map(s => `<li>${s}</li>`).join('')}
                    </ul>
                </div>

                <div>
                    <h4 class="text-xs font-bold text-slate-700 mb-1.5 flex items-center gap-1.5">
                        <i class="fa-solid fa-user-doctor text-teal-600"></i>
                        <span>${currentLang === 'lo' ? 'ວິທີການຮັກສາ & ຂັ້ນຕອນການໃຫ້ຢາ:' : 'แนวทางการรักษา & การใช้ยา:'}</span>
                    </h4>
                    <ul class="text-xs text-slate-700 space-y-1.5 leading-relaxed bg-emerald-50/50 p-3 rounded-xl border border-emerald-100">
                        ${treatments.map(t => `<li class="flex items-start gap-1.5"><i class="fa-solid fa-check text-teal-600 mt-1 text-[10px]"></i><span>${t}</span></li>`).join('')}
                    </ul>
                </div>
            </div>

            <div class="mt-4 pt-3 border-t border-slate-100 space-y-3">
                <div>
                    <span class="block text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-2">
                        ${currentLang === 'lo' ? 'ຢາທີ່ໃຊ້ປິ່ນປົວ (ກົດເພື່ອເບິ່ງລາຄາ, ຂະໜາດສັກ & ຄິດໄລ່ cc):' : 'ยาที่ใช้รักษา (กดเพื่อดูราคา ขนาด และคำนวณ cc):'}
                    </span>
                    <div class="flex flex-wrap gap-1.5">
                        ${drugButtonsHtml}
                    </div>
                </div>
                <button onclick="openConsultWhatsApp('${safeTitle}')" class="w-full py-2 px-3 rounded-xl bg-emerald-50 hover:bg-emerald-600 text-emerald-800 hover:text-white border border-emerald-200 text-xs font-bold flex items-center justify-center gap-1.5 transition">
                    <i class="fa-brands fa-whatsapp text-sm"></i>
                    <span>${currentLang === 'lo' ? 'ສັດມີອາການນີ້? ກົດປຶກສາ ຫຼື ສັ່ງຊຸດຢາທາງ WhatsApp' : 'สัตว์มีอาการนี้? กดปรึกษาหรือสั่งชุดยาทาง WhatsApp'}</span>
                </button>
            </div>
        `;

        grid.appendChild(card);
    });
}

// ============================================================================
// 8. ລະບົບໜ້າຮ້ານ & ກະຕ່າສັ່ງຊື້ເອງແບບ LAOCART (3-STEP SELF-CHECKOUT SYSTEM)
// ============================================================================
let currentLaocartPill = 'all';
let detailModalQty = 1;
let cartItems = []; // [{ key, drugId, name, image, size, unitPrice, qty, isBundle }]
let cartStep = 0;   // 0 = Cart, 1 = Step 1/3 Address, 2 = Step 2/3 Courier, 3 = Step 3/3 Confirm & QR, 4 = Done
let selectedCourier = 'anousith'; // 'anousith' | 'mixay' | 'hal'
let appliedCoupon = null; // e.g. 'NEW5'
let uploadedSlipDataUrl = null;
let lastCompletedOrder = null;

const LAO_PROVINCES = [
    'ນະຄອນຫຼວງວຽງຈັນ',
    'ສະຫວັນນະເຂດ',
    'ຈຳປາສັກ',
    'ຫຼວງພະບາງ',
    'ວຽງຈັນ',
    'ຄຳມ່ວນ',
    'ບໍລິຄຳໄຊ',
    'ໄຊຍະບູລີ',
    'ຊຽງຂວາງ',
    'ອຸດົມໄຊ',
    'ບໍ່ແກ້ວ',
    'ຫຼວງນ້ຳທາ',
    'ຜົ້ງສາລີ',
    'ຫົວພັນ',
    'ສາລະວັນ',
    'ເຊກອງ',
    'ອັດຕະປື',
    'ໄຊສົມບູນ'
];

const COURIER_OPTIONS = {
    anousith: { id: 'anousith', name: 'ອະນຸສິດ', fullName: 'ອະນຸສິດ (Anousith Express)', fee: 0, feeLabel: 'ຟຣີ', badgeColor: 'bg-slate-900 text-white', subColor: 'text-rose-600' },
    mixay:    { id: 'mixay',    name: 'ມີໄຊ',    fullName: 'ມີໄຊ (MIXAY Express)',       fee: 5000, feeLabel: '5,000 ກີບ', badgeColor: 'bg-red-600 text-white', subColor: 'text-amber-300' },
    hal:      { id: 'hal',      name: 'ຮຸ່ງອາລຸນ', fullName: 'ຮຸ່ງອາລຸນ (HAL Logistics)',   fee: 5000, feeLabel: '5,000 ກີບ', badgeColor: 'bg-rose-700 text-white', subColor: 'text-white' }
};

let customerInfo = {
    name: '',
    phone: '',
    province: 'ນະຄອນຫຼວງວຽງຈັນ',
    district: '',
    village: '',
    note: ''
};

function parseKipPrice(priceStr) {
    if (!priceStr) return 0;
    const digits = String(priceStr).replace(/[^0-9]/g, '');
    return parseInt(digits, 10) || 0;
}

function formatKip(num) {
    return Number(num || 0).toLocaleString('en-US') + ' ກີບ';
}

function getOriginalPriceKip(salePriceNum) {
    if (!salePriceNum) return 0;
    const raw = Math.round((salePriceNum * 1.05) / 1000) * 1000;
    return raw <= salePriceNum ? salePriceNum + 5000 : raw;
}

function loadCartFromStorage() {
    try {
        const savedCart = localStorage.getItem('vetdrug_laocart_items');
        if (savedCart) cartItems = JSON.parse(savedCart) || [];
        const savedCust = localStorage.getItem('vetdrug_laocart_customer');
        if (savedCust) customerInfo = { ...customerInfo, ...JSON.parse(savedCust) };
    } catch (e) {}
    updateCartBadges();
}

function saveCartToStorage() {
    try {
        localStorage.setItem('vetdrug_laocart_items', JSON.stringify(cartItems));
        localStorage.setItem('vetdrug_laocart_customer', JSON.stringify(customerInfo));
    } catch (e) {}
    updateCartBadges();
}

function getTotalCartCount() {
    return cartItems.reduce((sum, item) => sum + item.qty, 0);
}

function getCartSubtotal() {
    return cartItems.reduce((sum, item) => sum + (item.unitPrice * item.qty), 0);
}

function updateCartBadges() {
    const totalCount = getTotalCartCount();
    const badgeIds = ['cart-count-badge', 'detail-cart-badge'];
    badgeIds.forEach(id => {
        const el = document.getElementById(id);
        if (!el) return;
        el.innerText = totalCount;
        if (totalCount > 0) {
            el.classList.remove('hidden');
        } else {
            el.classList.add('hidden');
        }
    });

    const textIds = ['mnav-cart-count', 'floating-cart-count', 'checkout-header-badge'];
    textIds.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.innerText = totalCount;
    });
}

let toastTimer = null;
function showCartToast(msg) {
    const toast = document.getElementById('cart-toast');
    const textEl = document.getElementById('cart-toast-text');
    if (!toast || !textEl) return;
    textEl.innerText = msg;
    toast.classList.remove('opacity-0', '-translate-y-2');
    toast.classList.add('opacity-100', 'translate-y-0');
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(() => {
        toast.classList.remove('opacity-100', 'translate-y-0');
        toast.classList.add('opacity-0', '-translate-y-2');
    }, 2200);
}

function copyCouponCode(code) {
    appliedCoupon = code;
    try {
        navigator.clipboard.writeText(code);
    } catch (e) {}
    const btnText = document.getElementById('coupon-btn-text');
    if (btnText) btnText.innerText = `✓ ກ໊ອບປີ້ ${code} ແລ້ວ!`;
    showCartToast(`🎁 ກ໊ອບປີ້ລະຫັດສ່ວນຫຼຸດ ${code} (ຫຼຸດ 5%) ຮຽບຮ້ອຍແລ້ວ!`);
}

function setLaocartPillFilter(pillVal) {
    currentLaocartPill = pillVal;
    currentCategory = 'all';
    currentAnimal = 'all';
    currentQuickFilter = null;

    if (['poultry', 'cattle', 'pig', 'goat', 'pet'].includes(pillVal)) {
        currentAnimal = pillVal;
    } else if (['antibiotic', 'dewormer', 'vitamin', 'nsaid', 'wound', 'hormone', 'allergy', 'digestive'].includes(pillVal)) {
        currentCategory = pillVal;
    } else if (pillVal === 'pregnant-safe') {
        currentQuickFilter = 'pregnant-safe';
    }

    document.querySelectorAll('.lpill-btn').forEach(btn => {
        if (btn.getAttribute('data-lpill') === pillVal) {
            btn.className = "lpill-btn shrink-0 px-4 py-2 rounded-full text-xs sm:text-sm font-extrabold bg-rose-600 text-white shadow-sm transition";
        } else {
            btn.className = "lpill-btn shrink-0 px-4 py-2 rounded-full text-xs sm:text-sm font-bold bg-white hover:bg-rose-50 text-slate-700 border border-slate-200 transition";
        }
    });

    renderDrugGrid();
}

function updateQuickPillState() {
    // Kept for compatibility with search input & symptom bar
}

function addToCartItem({ key, drugId, name, image, size, unitPrice, qty, isBundle }) {
    const existing = cartItems.find(item => item.key === key);
    if (existing) {
        existing.qty += qty;
    } else {
        cartItems.push({ key, drugId, name, image, size, unitPrice, qty, isBundle: !!isBundle });
    }
    saveCartToStorage();
    showCartToast(`🛒 ເພີ່ມ "${name}" (${size}) ໃສ່ກະຕ່າແລ້ວ!`);
}

function addToCartQuick(drugId) {
    const drug = DRUGS_DATA.find(d => d.id === drugId);
    if (!drug || !drug.sizes || drug.sizes.length === 0) return;
    const sizeIdx = selectedSizes[drug.id] || 0;
    const chosen = drug.sizes[sizeIdx] || drug.sizes[0];
    const unitPrice = parseKipPrice(chosen.price);
    addToCartItem({
        key: `${drug.id}__${chosen.size}`,
        drugId: drug.id,
        name: drug.name,
        image: drug.image || '',
        size: chosen.size,
        unitPrice,
        qty: 1,
        isBundle: false
    });
}

function addBundleToCart(bundleId) {
    const b = BUNDLES_DATA.find(item => item.id === bundleId);
    if (!b) return;
    const title = currentLang === 'lo' ? b.title_lo : b.title_th;
    const firstDrug = DRUGS_DATA.find(d => d.id === (b.items[0] && b.items[0].drugId));
    const unitPrice = parseKipPrice(b.totalPrice);
    addToCartItem({
        key: `bundle__${b.id}`,
        drugId: b.id,
        name: title,
        image: (firstDrug && firstDrug.image) ? firstDrug.image : '',
        size: 'ຊຸດຄົບເຊັດ',
        unitPrice,
        qty: 1,
        isBundle: true
    });
}

function renderDrugGrid() {
    const grid = document.getElementById('drug-grid');
    const emptyState = document.getElementById('empty-state');
    const countBadge = document.getElementById('showing-count-badge');
    if (!grid) return;
    grid.innerHTML = '';

    const activeSymptomObj = currentSymptomFilter
        ? SYMPTOM_FILTERS.find(s => s.id === currentSymptomFilter)
        : null;

    const filtered = DRUGS_DATA.filter(drug => {
        const matchSearch = currentSearch === '' || 
            drug.name.toLowerCase().includes(currentSearch) ||
            drug.active.toLowerCase().includes(currentSearch) ||
            drug.indications_lo.some(i => i.toLowerCase().includes(currentSearch)) ||
            drug.indications_th.some(i => i.toLowerCase().includes(currentSearch));

        const matchCat = currentCategory === 'all' || drug.category === currentCategory;
        const matchAnimal = currentAnimal === 'all' || drug.species.includes(currentAnimal);

        let matchQuick = true;
        if (currentQuickFilter === 'pregnant-safe') {
            matchQuick = drug.pregnancy === 'safe';
        } else if (currentQuickFilter === 'pregnant-warn') {
            matchQuick = drug.pregnancy === 'danger' || drug.pregnancy === 'caution';
        } else if (currentQuickFilter === 'livestock') {
            matchQuick = drug.species.some(s => ['cattle', 'pig', 'goat'].includes(s));
        } else if (currentQuickFilter === 'poultry') {
            matchQuick = drug.species.includes('poultry');
        }

        const matchSymptom = !activeSymptomObj || activeSymptomObj.drugIds.includes(drug.id);

        return matchSearch && matchCat && matchAnimal && matchQuick && matchSymptom;
    });

    if (countBadge) {
        countBadge.innerText = currentLang === 'lo'
            ? `${filtered.length} ລາຍການ`
            : `${filtered.length} รายการ`;
    }

    if (filtered.length === 0) {
        emptyState.classList.remove('hidden');
        return;
    } else {
        emptyState.classList.add('hidden');
    }

    filtered.forEach(drug => {
        const card = document.createElement('div');
        card.className = "bg-white rounded-2xl border border-slate-200/90 shadow-sm hover:shadow-lg transition-all overflow-hidden flex flex-col justify-between group";

        // Pregnancy Badge
        let pregBadge = '';
        if (drug.pregnancy === 'safe') {
            pregBadge = `<span class="px-1.5 sm:px-2 py-0.5 rounded-full text-[9px] sm:text-[10px] font-bold bg-emerald-50/95 text-emerald-700 border border-emerald-200 inline-flex items-center gap-0.5">
                <i class="fa-solid fa-check"></i> <span class="hidden sm:inline">${I18N[currentLang].safeTag}</span><span class="sm:hidden">ຖືພາໄດ້</span>
            </span>`;
        } else if (drug.pregnancy === 'caution') {
            pregBadge = `<span class="px-1.5 sm:px-2 py-0.5 rounded-full text-[9px] sm:text-[10px] font-bold bg-amber-50/95 text-amber-700 border border-amber-200 inline-flex items-center gap-0.5">
                <i class="fa-solid fa-circle-exclamation"></i> <span class="hidden sm:inline">${I18N[currentLang].cautionTag}</span><span class="sm:hidden">ລະວັງ</span>
            </span>`;
        } else {
            pregBadge = `<span class="px-1.5 sm:px-2 py-0.5 rounded-full text-[9px] sm:text-[10px] font-bold bg-rose-50/95 text-rose-700 border border-rose-200 inline-flex items-center gap-0.5">
                <i class="fa-solid fa-triangle-exclamation"></i> <span class="hidden sm:inline">${I18N[currentLang].dangerTag}</span><span class="sm:hidden">ຫ້າມທ້ອງ</span>
            </span>`;
        }

        const isBestSeller = BEST_SELLER_IDS.has(drug.id);
        const discountBadge = `<span class="px-2 py-0.5 rounded-md text-[10px] sm:text-[11px] font-extrabold bg-rose-600 text-white shadow-sm">-5%</span>`;
        const bestSellerBadge = isBestSeller
            ? `<span class="px-1.5 py-0.5 rounded-md text-[9px] sm:text-[10px] font-extrabold bg-amber-400 text-slate-950 shadow-sm">${I18N[currentLang].bestSeller}</span>`
            : '';

        const indicationList = currentLang === 'lo' ? drug.indications_lo : drug.indications_th;
        const ratioText = currentLang === 'lo' ? drug.ratioText_lo : drug.ratioText_th;

        // Active size & price
        const activeSizeIdx = selectedSizes[drug.id] || 0;
        const chosenSizeObj = (drug.sizes && drug.sizes[activeSizeIdx]) ? drug.sizes[activeSizeIdx] : drug.sizes[0];
        const salePriceNum = parseKipPrice(chosenSizeObj.price);
        const origPriceNum = getOriginalPriceKip(salePriceNum);

        // Product Image Header (Laocart clean square/rectangular card header)
        const imgHeightClass = mobileGridCols === 1 ? 'h-48 sm:h-48' : 'h-36 sm:h-48';
        const safeCaption = drug.name.replace(/'/g, "\\'");
        const mediaHeaderHtml = `
            <div class="relative ${imgHeightClass} bg-slate-100 border-b border-slate-100 overflow-hidden cursor-pointer" onclick="openDetailModal('${drug.id}')">
                <img src="${drug.image}" alt="${drug.name}" loading="lazy" class="w-full h-full object-contain p-1.5 sm:p-2.5 group-hover:scale-105 transition-transform duration-300">
                <div class="absolute top-2 left-2 flex flex-wrap gap-1">
                    ${discountBadge}
                    ${bestSellerBadge}
                </div>
                <div class="absolute top-2 right-2">
                    ${pregBadge}
                </div>
                <button onclick="event.stopPropagation(); openImageLightbox('${drug.image}', '${safeCaption}')" class="absolute bottom-1.5 right-1.5 w-6 h-6 sm:w-7 sm:h-7 rounded-lg bg-white/90 hover:bg-white text-slate-700 shadow flex items-center justify-center text-[10px] sm:text-xs" title="ຂະຫຍາຍຮູບ">
                    <i class="fa-solid fa-magnifying-glass-plus"></i>
                </button>
            </div>
        `;

        // Size selector pills if multiple sizes
        let sizePillsHtml = '';
        if (drug.sizes && drug.sizes.length > 1) {
            sizePillsHtml = `
                <div class="flex flex-wrap gap-1 mt-1.5">
                    ${drug.sizes.map((s, idx) => {
                        const isSel = idx === activeSizeIdx;
                        const cls = isSel
                            ? "px-2 py-0.5 rounded-md bg-rose-50 border border-rose-500 text-rose-700 text-[10px] font-extrabold"
                            : "px-2 py-0.5 rounded-md bg-slate-100 hover:bg-slate-200 text-slate-600 text-[10px] font-semibold";
                        return `<button type="button" onclick="selectDrugSize('${drug.id}', ${idx})" class="${cls}">${s.size}</button>`;
                    }).join('')}
                </div>
            `;
        } else {
            sizePillsHtml = `<span class="inline-block mt-1 text-[10px] font-semibold text-slate-400">ຂະໜາດ: ${chosenSizeObj.size}</span>`;
        }

        // Primary Button: ທັກ WhatsApp (ສົ່ງຊື່ຢາ + ຂະໜາດທີ່ເລືອກ ໄປຫາຮ້ານອັດຕະໂນມັດ)
        const primaryBtnHtml = `<button onclick="openWhatsAppDrug('${drug.id}')" class="w-full py-2 sm:py-2.5 px-3 rounded-xl bg-emerald-600 hover:bg-emerald-700 active:scale-[0.98] text-white text-xs sm:text-sm font-extrabold transition shadow-sm flex items-center justify-center gap-1.5">
                    <i class="fa-brands fa-whatsapp text-sm"></i>
                    <span>ທັກ WhatsApp</span>
               </button>`;

        card.innerHTML = `
            <div>
                ${mediaHeaderHtml}
                <div class="p-2.5 sm:p-4">
                    <h3 onclick="openDetailModal('${drug.id}')" class="font-extrabold text-slate-900 text-xs sm:text-base leading-snug group-hover:text-rose-600 transition cursor-pointer line-clamp-1">${drug.name}</h3>
                    
                    <!-- Laocart Price Row (Bold Rose Price + Crossed-out Original Price) -->
                    <div class="mt-1 flex items-baseline gap-1.5 flex-wrap">
                        <span class="text-sm sm:text-base font-extrabold text-rose-600">${chosenSizeObj.price}</span>
                        <span class="text-[10px] sm:text-xs text-slate-400 line-through">${formatKip(origPriceNum)}</span>
                    </div>

                    ${sizePillsHtml}

                    <div class="mt-2 pt-1.5 border-t border-slate-100">
                        <p class="text-[10px] sm:text-xs text-slate-600 line-clamp-2 leading-relaxed">
                            ${indicationList[0]}
                        </p>
                        <div class="mt-1 flex items-center gap-1 text-[10px] text-teal-700 font-semibold truncate">
                            <i class="fa-solid fa-syringe text-[9px]"></i>
                            <span class="truncate">${ratioText}</span>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Laocart Primary Action + Quick Detail/Dose Info -->
            <div class="px-2.5 pb-2.5 pt-0.5 sm:px-4 sm:pb-4 flex flex-col gap-1.5">
                ${primaryBtnHtml}
                <div class="flex items-center justify-between gap-1 text-[10px] sm:text-xs pt-0.5">
                    <button onclick="openDetailModal('${drug.id}')" class="text-slate-500 hover:text-teal-700 font-semibold flex items-center gap-1 truncate">
                        <i class="fa-solid fa-circle-info text-teal-600"></i>
                        <span>ວິທີໃຊ້ & ລາຍລະອຽດ</span>
                    </button>
                    <button onclick="openCalculator('${drug.id}')" class="text-teal-700 hover:underline font-bold shrink-0">
                        <i class="fa-solid fa-calculator"></i> cc
                    </button>
                </div>
            </div>
        `;

        grid.appendChild(card);
    });
}

function selectDetailSize(drugId, idx) {
    selectedSizes[drugId] = idx;
    openDetailModal(drugId);
    renderDrugGrid();
}

function changeDetailQty(delta) {
    detailModalQty = Math.max(1, detailModalQty + delta);
    const qtyEl = document.getElementById('detail-qty-val');
    if (qtyEl) qtyEl.innerText = detailModalQty;
}

function addFromDetailToCart() {
    const modal = document.getElementById('detail-modal');
    const drugId = modal ? modal.dataset.activeDrugId : null;
    const drug = DRUGS_DATA.find(d => d.id === drugId);
    if (!drug || !drug.sizes || drug.sizes.length === 0) return;

    const sizeIdx = selectedSizes[drug.id] || 0;
    const chosen = drug.sizes[sizeIdx] || drug.sizes[0];
    const unitPrice = parseKipPrice(chosen.price);

    addToCartItem({
        key: `${drug.id}__${chosen.size}`,
        drugId: drug.id,
        name: drug.name,
        image: drug.image || '',
        size: chosen.size,
        unitPrice,
        qty: detailModalQty,
        isBundle: false
    });
}

function shareCurrentDrug() {
    const modal = document.getElementById('detail-modal');
    const drugId = modal ? modal.dataset.activeDrugId : null;
    const drug = DRUGS_DATA.find(d => d.id === drugId);
    if (!drug) return;
    const text = `${drug.name} - ຮ້ານຂາຍຢາສັດ ນິຍົມ ການກະເສດ (${window.location.href})`;
    if (navigator.share) {
        navigator.share({ title: drug.name, text, url: window.location.href }).catch(() => {});
    } else {
        try { navigator.clipboard.writeText(text); } catch (e) {}
        showCartToast('🔗 ກ໊ອບປີ້ລິ້ງສິນຄ້າແລ້ວ!');
    }
}

function openDetailModal(drugId) {
    const drug = DRUGS_DATA.find(d => d.id === drugId);
    if (!drug) return;

    const modal = document.getElementById('detail-modal');
    const isSameDrug = modal.dataset.activeDrugId === drug.id && !modal.classList.contains('hidden');
    modal.dataset.activeDrugId = drug.id;
    if (!isSameDrug) {
        detailModalQty = 1;
        const qtyEl = document.getElementById('detail-qty-val');
        if (qtyEl) qtyEl.innerText = '1';
    }

    // Image / Icon thumbnail
    const imgEl = document.getElementById('detail-image');
    const iconEl = document.getElementById('detail-icon');
    if (drug.image && drug.image.trim() !== '') {
        imgEl.src = drug.image;
        imgEl.alt = drug.name;
        imgEl.classList.remove('hidden');
        iconEl.classList.add('hidden');
    } else {
        imgEl.src = '';
        imgEl.classList.add('hidden');
        iconEl.classList.remove('hidden');
        iconEl.innerHTML = `<i class="${drug.icon}"></i>`;
    }

    // Basic Info
    document.getElementById('detail-name').innerText = drug.name;
    document.getElementById('detail-active').innerText = drug.active;
    document.getElementById('detail-badge').innerText = I18N[currentLang].categoryMap[drug.category] || drug.category;
    document.getElementById('detail-code-badge').innerText = `✅ ${I18N[currentLang].inStock}`;

    // Active Size & Laocart Price Highlight (Matches Video 00:15: 299,000 ກີບ  313,000 ກີບ  [-4%] [ລາຄາພິເສດ])
    const activeSizeIdx = selectedSizes[drug.id] || 0;
    const chosenSize = (drug.sizes && drug.sizes[activeSizeIdx]) ? drug.sizes[activeSizeIdx] : drug.sizes[0];
    const salePriceNum = parseKipPrice(chosenSize.price);
    const origPriceNum = getOriginalPriceKip(salePriceNum);

    const priceHighlight = document.getElementById('detail-price-highlight');
    if (priceHighlight) {
        priceHighlight.innerHTML = `
            <span class="text-xl sm:text-2xl font-extrabold text-rose-600">${chosenSize.price}</span>
            <span class="text-xs sm:text-sm text-slate-400 line-through">${formatKip(origPriceNum)}</span>
            <span class="px-2 py-0.5 rounded-md bg-rose-600 text-white text-xs font-extrabold">-5%</span>
        `;
    }

    // Selectable Sizes
    const pricesWrap = document.getElementById('detail-prices');
    pricesWrap.innerHTML = '';
    if (drug.sizes && drug.sizes.length > 0) {
        drug.sizes.forEach((s, idx) => {
            const isSel = idx === activeSizeIdx;
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.onclick = () => selectDetailSize(drug.id, idx);
            btn.className = isSel
                ? "inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl bg-rose-50 border-2 border-rose-600 text-xs font-extrabold text-rose-700 shadow-sm transition"
                : "inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl bg-white hover:bg-slate-50 border border-slate-200 text-xs font-bold text-slate-700 transition";
            btn.innerHTML = `<span>ຂະໜາດ ${s.size}</span> <span class="text-slate-400">•</span> <span>${s.price}</span>`;
            pricesWrap.appendChild(btn);
        });
    }

    // Pregnancy Alert Box
    const pregBox = document.getElementById('detail-pregnancy-box');
    const pregTitle = document.getElementById('detail-preg-title');
    const pregDesc = document.getElementById('detail-preg-desc');
    const pregIcon = document.getElementById('detail-preg-icon');

    if (drug.pregnancy === 'safe') {
        pregBox.className = "p-3.5 rounded-xl border flex items-start gap-3 bg-emerald-50 border-emerald-200 text-emerald-900";
        pregIcon.className = "fa-solid fa-shield-heart text-base text-emerald-600 mt-0.5";
        pregTitle.innerText = currentLang === 'lo' ? 'ປອດໄພໃນສັດຖືພາ (Pregnancy Safe)' : 'ปลอดภัยในสัตว์ตั้งท้อง';
        pregDesc.innerText = currentLang === 'lo' ? drug.pregnancyNote_lo : drug.pregnancyNote_th;
    } else if (drug.pregnancy === 'caution') {
        pregBox.className = "p-3.5 rounded-xl border flex items-start gap-3 bg-amber-50 border-amber-200 text-amber-900";
        pregIcon.className = "fa-solid fa-circle-exclamation text-base text-amber-600 mt-0.5";
        pregTitle.innerText = currentLang === 'lo' ? 'ຄວນລະວັງໃນສັດຖືພາ (Use with Caution)' : 'ควรระวังในสัตว์ตั้งท้อง';
        pregDesc.innerText = currentLang === 'lo' ? drug.pregnancyNote_lo : drug.pregnancyNote_th;
    } else {
        pregBox.className = "p-3.5 rounded-xl border flex items-start gap-3 bg-rose-50 border-rose-200 text-rose-900";
        pregIcon.className = "fa-solid fa-triangle-exclamation text-base text-rose-600 mt-0.5";
        pregTitle.innerText = currentLang === 'lo' ? 'ຫ້າມໃຊ້ໃນສັດຖືພາເດັດຂາດ / ອັນຕະລາຍສູງ' : 'ห้ามใช้ในสัตว์ตั้งท้องเด็ดขาด / อันตรายสูง';
        pregDesc.innerText = currentLang === 'lo' ? drug.pregnancyNote_lo : drug.pregnancyNote_th;
    }

    // Indications
    const indList = document.getElementById('detail-indications');
    indList.innerHTML = '';
    const indications = currentLang === 'lo' ? drug.indications_lo : drug.indications_th;
    indications.forEach(ind => {
        const li = document.createElement('li');
        li.innerText = ind;
        indList.appendChild(li);
    });

    // Dosage Table
    const dosageBody = document.getElementById('detail-dosage-table');
    dosageBody.innerHTML = '';
    drug.dosage.forEach(d => {
        const tr = document.createElement('tr');
        tr.className = "hover:bg-slate-50 transition";
        tr.innerHTML = `
            <td class="p-2.5 font-semibold text-slate-800">${d.animal}</td>
            <td class="p-2.5 text-slate-700">${d.dose}</td>
            <td class="p-2.5 text-teal-700 font-medium">${d.route}</td>
        `;
        dosageBody.appendChild(tr);
    });

    // Summary & Practical Guide
    document.getElementById('detail-rate-summary').innerText = currentLang === 'lo' ? drug.ratioText_lo : drug.ratioText_th;
    const practicalBox = document.getElementById('detail-practical-guide');
    if (practicalBox) {
        const practical = getPracticalDrugGuide(drug);
        practicalBox.innerHTML = `
            <div class="bg-white/80 p-2.5 rounded-lg border border-teal-200/80">
                <div class="font-bold text-teal-900 flex items-center gap-1.5 mb-0.5">
                    <i class="fa-solid fa-vial text-teal-600"></i>
                    <span>${I18N[currentLang].bottleCoverageTitle}</span>
                </div>
                <p class="text-slate-700 leading-snug">${practical.coverage}</p>
            </div>
            <div class="bg-white/80 p-2.5 rounded-lg border border-teal-200/80">
                <div class="font-bold text-teal-900 flex items-center gap-1.5 mb-0.5">
                    <i class="fa-solid fa-syringe text-teal-600"></i>
                    <span>${I18N[currentLang].needleGuideTitle}</span>
                </div>
                <p class="text-slate-700 leading-snug">${practical.needle}</p>
            </div>
        `;
    }

    // Warnings
    const warnList = document.getElementById('detail-warnings');
    warnList.innerHTML = '';
    const warnings = currentLang === 'lo' ? drug.warnings_lo : drug.warnings_th;
    warnings.forEach(w => {
        const li = document.createElement('li');
        li.innerText = w;
        warnList.appendChild(li);
    });

    updateCartBadges();
    modal.classList.remove('hidden');
}

function closeDetailModal() {
    document.getElementById('detail-modal').classList.add('hidden');
}

// ============================================================================
// 9. ຟັງຊັນຄວບຄຸມກະຕ່າສິນຄ້າ & ຂັ້ນຕອນການສັ່ງຊື້ 1/3 -> 2/3 -> 3/3 (LAOCART FLOW)
// ============================================================================
function openCartModal(startStep = 0) {
    cartStep = startStep;
    const modal = document.getElementById('cart-checkout-modal');
    if (!modal) return;
    modal.classList.remove('hidden');
    renderCheckoutModal();
}

function closeCartModal() {
    const modal = document.getElementById('cart-checkout-modal');
    if (modal) modal.classList.add('hidden');
}

function updateCartItemQty(key, delta) {
    const idx = cartItems.findIndex(item => item.key === key);
    if (idx === -1) return;
    cartItems[idx].qty += delta;
    if (cartItems[idx].qty <= 0) {
        cartItems.splice(idx, 1);
    }
    saveCartToStorage();
    renderCheckoutModal();
}

function removeCartItem(key) {
    cartItems = cartItems.filter(item => item.key !== key);
    saveCartToStorage();
    renderCheckoutModal();
}

function goToCheckoutStep(step) {
    if (step === 2) {
        // Save and validate Step 1 fields
        const nameEl = document.getElementById('chk-name');
        const phoneEl = document.getElementById('chk-phone');
        const provEl = document.getElementById('chk-province');
        const distEl = document.getElementById('chk-district');
        const villEl = document.getElementById('chk-village');
        const noteEl = document.getElementById('chk-note');

        if (nameEl) customerInfo.name = nameEl.value.trim();
        if (phoneEl) customerInfo.phone = phoneEl.value.trim();
        if (provEl) customerInfo.province = provEl.value.trim();
        if (distEl) customerInfo.district = distEl.value.trim();
        if (villEl) customerInfo.village = villEl.value.trim();
        if (noteEl) customerInfo.note = noteEl.value.trim();
        saveCartToStorage();

        if (!customerInfo.name || !customerInfo.phone || !customerInfo.district || !customerInfo.village) {
            const errEl = document.getElementById('chk-step1-error');
            if (errEl) {
                errEl.innerText = '⚠️ ກະລຸນາປ້ອນ ຊື່, ເບີໂທ, ເມືອງ ແລະ ບ້ານ/ສາຂາຂົນສົ່ງ ໃຫ້ຄົບຖ້ວນກ່ອນໄປຂັ້ນຕອນຕໍ່ໄປ';
                errEl.classList.remove('hidden');
            }
            return;
        }
    }
    cartStep = step;
    renderCheckoutModal();
}

function selectCourier(courierId) {
    if (COURIER_OPTIONS[courierId]) {
        selectedCourier = courierId;
        renderCheckoutModal();
    }
}

function applyDiscountCoupon() {
    const input = document.getElementById('chk-coupon-input');
    if (!input) return;
    const code = input.value.trim().toUpperCase();
    if (code === 'NEW5' || code === 'NEWMEILI' || code === 'NIYOM5') {
        appliedCoupon = code;
        showCartToast(`🎉 ໃຊ້ລະຫັດສ່ວນຫຼຸດ ${code} (ຫຼຸດ 5%) ສຳເລັດ!`);
    } else if (code === '') {
        appliedCoupon = null;
    } else {
        showCartToast('⚠️ ລະຫັດສ່ວນຫຼຸດບໍ່ຖືກຕ້ອງ (ລອງໃຊ້ລະຫັດ: NEW5)');
        return;
    }
    renderCheckoutModal();
}

function handleSlipUpload(event) {
    const file = event.target.files && event.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function(e) {
        uploadedSlipDataUrl = e.target.result;
        renderCheckoutModal();
        showCartToast('✅ ແນບຮູບໃບໂອນເງິນ BCEL One ຮຽບຮ້ອຍແລ້ວ!');
    };
    reader.readAsDataURL(file);
}

function getOrderTotals() {
    const subtotal = getCartSubtotal();
    const courierObj = COURIER_OPTIONS[selectedCourier] || COURIER_OPTIONS.anousith;
    const shippingFee = courierObj.fee;
    const discountAmount = appliedCoupon ? Math.round((subtotal * 0.05) / 500) * 500 : 0;
    const grandTotal = Math.max(0, subtotal - discountAmount + shippingFee);
    return { subtotal, shippingFee, discountAmount, grandTotal, courierObj };
}

function submitLaocartOrder() {
    if (cartItems.length === 0) return;
    const { subtotal, shippingFee, discountAmount, grandTotal, courierObj } = getOrderTotals();
    const now = new Date();
    const orderId = 'ORD-' + now.getFullYear().toString().slice(-2) +
        String(now.getMonth() + 1).padStart(2, '0') +
        String(now.getDate()).padStart(2, '0') + '-' +
        Math.floor(1000 + Math.random() * 9000);

    const newOrder = {
        orderId,
        createdAt: now.toISOString(),
        customer: { ...customerInfo },
        courier: courierObj,
        items: cartItems.map(i => ({ ...i })),
        subtotal,
        shippingFee,
        coupon: appliedCoupon,
        discountAmount,
        grandTotal,
        hasSlip: !!uploadedSlipDataUrl
    };

    lastCompletedOrder = newOrder;

    // Save to local server orders.json (non-blocking)
    fetch('/api/orders', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newOrder)
    }).catch(() => {});

    // Clear cart after order completion
    cartItems = [];
    uploadedSlipDataUrl = null;
    saveCartToStorage();
    cartStep = 4;
    renderCheckoutModal();
}

function sendOrderBillWhatsApp() {
    if (!lastCompletedOrder) return;
    const o = lastCompletedOrder;
    const lines = [
        `🧾 *ບິນສັ່ງຊື້ສິນຄ້າຜ່ານເວັບ (ຮ້ານ ນິຍົມ ການກະເສດ)*`,
        `ລະຫັດບິນ: *#${o.orderId}*`,
        `------------------------`,
        `👤 *ຂໍ້ມູນຜູ້ຮັບສິນຄ້າ:*`,
        `• ຊື່: ${o.customer.name}`,
        `• ເບີໂທ: ${o.customer.phone}`,
        `• ທີ່ຢູ່/ສາຂາ: ${o.customer.village}, ເມືອງ${o.customer.district}, ${o.customer.province}`,
        o.customer.note ? `• ໝາຍເຫດ: ${o.customer.note}` : null,
        `🚚 *ບໍລິສັດຂົນສົ່ງ:* ${o.courier.fullName} (${o.courier.feeLabel})`,
        `------------------------`,
        `📦 *ລາຍການສິນຄ້າ:*`,
        ...o.items.map((item, idx) => `${idx + 1}. ${item.name} (${item.size}) × ${item.qty} = ${formatKip(item.unitPrice * item.qty)}`),
        `------------------------`,
        `• ລາຄາສິນຄ້າ: ${formatKip(o.subtotal)}`,
        `• ຄ່າແພັກ: ຟຣີ`,
        o.discountAmount > 0 ? `• ສ່ວນຫຼຸດ (${o.coupon}): -${formatKip(o.discountAmount)}` : null,
        o.shippingFee > 0 ? `• ຄ່າຝາກຂົນສົ່ງ: ${formatKip(o.shippingFee)}` : null,
        `💰 *ຍອດລວມທັງໝົດ: ${formatKip(o.grandTotal)}*`,
        `------------------------`,
        `✅ ຊຳລະຜ່ານ QR BCEL One (ດຽວສົ່ງຮູບໃບໂອນເງິນແນບໃຫ້ເດີ້)`
    ].filter(Boolean).join('\n');

    openWhatsAppCustom(lines);
}

function renderCheckoutModal() {
    const body = document.getElementById('cart-checkout-body');
    if (!body) return;
    updateCartBadges();

    // ====================================================
    // STEP 0: ກະຕ່າສິນຄ້າ (Shopping Cart View - Video 00:20)
    // ====================================================
    if (cartStep === 0) {
        if (cartItems.length === 0) {
            body.innerHTML = `
                <div class="bg-white rounded-2xl border border-slate-200 p-8 text-center space-y-3 my-4">
                    <div class="w-16 h-16 rounded-full bg-rose-50 text-rose-500 flex items-center justify-center mx-auto text-2xl">
                        <i class="fa-solid fa-cart-shopping"></i>
                    </div>
                    <h3 class="font-extrabold text-slate-900 text-base">ກະຕ່າສິນຄ້າຂອງທ່ານຍັງວ່າງຢູ່</h3>
                    <p class="text-xs text-slate-500">ເລືອກຊົມຢາສັດ ຫຼື ຊຸດຢາຈັດເຊັດ ແລ້ວກົດປຸ່ມ "ເພີ່ມໃສ່ກະຕ່າ" ໄດ້ເລີຍ</p>
                    <button onclick="closeCartModal()" class="mt-2 inline-flex items-center justify-center gap-2 px-6 py-3 rounded-xl bg-rose-600 hover:bg-rose-700 text-white text-xs sm:text-sm font-extrabold shadow-sm transition">
                        <span>ເລືອກຊື້ສິນຄ້າ</span>
                    </button>
                </div>
            `;
            return;
        }

        const subtotal = getCartSubtotal();
        const itemsHtml = cartItems.map(item => `
            <div class="bg-white rounded-2xl border border-slate-200 p-3.5 flex items-center gap-3 shadow-sm">
                <img src="${item.image}" alt="${item.name}" class="w-16 h-16 rounded-xl object-contain bg-slate-50 border border-slate-100 shrink-0">
                <div class="flex-grow min-w-0">
                    <div class="flex items-start justify-between gap-2">
                        <h4 class="font-extrabold text-slate-900 text-xs sm:text-sm truncate">${item.name}</h4>
                        <button onclick="removeCartItem('${item.key}')" class="text-slate-400 hover:text-rose-600 text-xs p-1">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                    <p class="text-[11px] text-slate-500 font-medium">ຕົວເລືອກ: ${item.size}</p>
                    <div class="mt-2 flex items-center justify-between gap-2">
                        <div class="inline-flex items-center rounded-lg border border-slate-200 bg-slate-50">
                            <button onclick="updateCartItemQty('${item.key}', -1)" class="w-7 h-7 flex items-center justify-center text-slate-700 hover:bg-slate-200 font-bold text-xs rounded-l-lg">−</button>
                            <span class="w-8 text-center text-xs font-extrabold text-slate-900">${item.qty}</span>
                            <button onclick="updateCartItemQty('${item.key}', 1)" class="w-7 h-7 flex items-center justify-center text-slate-700 hover:bg-slate-200 font-bold text-xs rounded-r-lg">+</button>
                        </div>
                        <span class="text-xs sm:text-sm font-extrabold text-slate-900">${formatKip(item.unitPrice * item.qty)}</span>
                    </div>
                </div>
            </div>
        `).join('');

        // Recommended "ອາດຈະມັກ" products (Video 00:20)
        const cartDrugIds = new Set(cartItems.map(i => i.drugId));
        const recDrugs = DRUGS_DATA.filter(d => !cartDrugIds.has(d.id) && BEST_SELLER_IDS.has(d.id)).slice(0, 2);
        const recHtml = recDrugs.map(d => {
            const firstSize = d.sizes[0];
            return `
                <div class="bg-white rounded-xl border border-slate-200 overflow-hidden shadow-sm flex flex-col justify-between">
                    <div class="relative h-28 bg-slate-100 cursor-pointer" onclick="closeCartModal(); openDetailModal('${d.id}')">
                        <img src="${d.image}" class="w-full h-full object-contain p-1.5">
                        <span class="absolute top-1.5 left-1.5 px-1.5 py-0.5 rounded bg-rose-600 text-white text-[9px] font-extrabold">-5%</span>
                    </div>
                    <div class="p-2.5">
                        <h5 class="font-bold text-slate-900 text-xs truncate">${d.name}</h5>
                        <p class="text-xs font-extrabold text-rose-600 mt-0.5">${firstSize.price}</p>
                        <button onclick="addToCartQuick('${d.id}'); renderCheckoutModal();" class="mt-2 w-full py-1.5 rounded-lg bg-rose-600 hover:bg-rose-700 text-white text-[11px] font-extrabold transition">
                            ເພີ່ມໃສ່ກະຕ່າ
                        </button>
                    </div>
                </div>
            `;
        }).join('');

        body.innerHTML = `
            <div class="space-y-4">
                <h2 class="text-lg sm:text-xl font-extrabold text-slate-900">ກະຕ່າສິນຄ້າ</h2>

                <div class="space-y-2.5">
                    ${itemsHtml}
                </div>

                <!-- Cart Summary Box (Exact match to video 00:20) -->
                <div class="bg-white rounded-2xl border border-slate-200 p-4 space-y-2.5 shadow-sm">
                    <div class="flex items-center justify-between text-xs sm:text-sm text-slate-600">
                        <span>ລາຄາສິນຄ້າ</span>
                        <span class="font-bold text-slate-900">${formatKip(subtotal)}</span>
                    </div>
                    <div class="flex items-center justify-between text-xs sm:text-sm text-slate-600">
                        <span>ຄ່າແພັກ</span>
                        <span class="font-extrabold text-emerald-600">ຟຣີ</span>
                    </div>
                    <div class="pt-2.5 border-t border-slate-100 flex items-center justify-between">
                        <span class="text-sm sm:text-base font-extrabold text-slate-900">ລວມທັງໝົດ</span>
                        <span class="text-base sm:text-lg font-extrabold text-rose-700">${formatKip(subtotal)}</span>
                    </div>
                </div>

                <!-- Primary "ສັ່ງຊື້" Button -->
                <button onclick="goToCheckoutStep(1)" class="w-full py-3.5 px-5 rounded-xl bg-rose-600 hover:bg-rose-700 active:scale-[0.99] text-white text-sm sm:text-base font-extrabold shadow-md shadow-rose-600/20 transition">
                    ສັ່ງຊື້
                </button>

                <div class="text-center">
                    <button onclick="closeCartModal()" class="text-xs sm:text-sm font-bold text-slate-500 hover:text-slate-800 underline">
                        ເລືອກຊື້ສິນຄ້າຕໍ່
                    </button>
                </div>

                <!-- "ອາດຈະມັກ" Section (Exact match to video 00:20) -->
                <div class="pt-4 border-t border-slate-200 space-y-2.5">
                    <h4 class="text-sm font-extrabold text-slate-800">ອາດຈະມັກ</h4>
                    <div class="grid grid-cols-2 gap-2.5">
                        ${recHtml}
                    </div>
                </div>
            </div>
        `;
        return;
    }

    // ====================================================
    // STEP 1/3: ຂໍ້ມູນຜູ້ຮັບສິນຄ້າ (Address Step - Video 00:22)
    // ====================================================
    if (cartStep === 1) {
        const provinceOptions = LAO_PROVINCES.map(p =>
            `<option value="${p}" ${customerInfo.province === p ? 'selected' : ''}>${p}</option>`
        ).join('');

        body.innerHTML = `
            <div class="space-y-4">
                <div>
                    <h2 class="text-lg font-extrabold text-slate-900">ດຳເນີນການສັ່ງຊື້</h2>
                    <p class="text-xs font-semibold text-slate-500 mt-0.5">ຂັ້ນຕອນ 1/3 · ຂໍ້ມູນຈັດສົ່ງ</p>
                    <!-- 3-Segment Progress Bar -->
                    <div class="grid grid-cols-3 gap-1.5 mt-2.5">
                        <div class="h-1.5 rounded-full bg-rose-600"></div>
                        <div class="h-1.5 rounded-full bg-slate-200"></div>
                        <div class="h-1.5 rounded-full bg-slate-200"></div>
                    </div>
                </div>

                <div id="chk-step1-error" class="hidden p-3 rounded-xl bg-rose-50 border border-rose-200 text-xs font-bold text-rose-700"></div>

                <div class="bg-white rounded-2xl border border-slate-200 p-4 space-y-3.5 shadow-sm">
                    <div>
                        <label class="block text-xs font-bold text-slate-700 mb-1">ຊື່ <span class="text-rose-600">*</span></label>
                        <input id="chk-name" type="text" value="${customerInfo.name}" placeholder="ປ້ອນຊື່ຜູ້ຮັບສິນຄ້າ..." class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 text-sm font-semibold focus:outline-none focus:ring-2 focus:ring-rose-500">
                    </div>

                    <div>
                        <label class="block text-xs font-bold text-slate-700 mb-1">ເບີໂທ <span class="text-rose-600">*</span></label>
                        <input id="chk-phone" type="tel" value="${customerInfo.phone}" placeholder="020 XXXX XXXX" class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 text-sm font-semibold focus:outline-none focus:ring-2 focus:ring-rose-500">
                    </div>

                    <div>
                        <label class="block text-xs font-bold text-slate-700 mb-1">ແຂວງ <span class="text-rose-600">*</span></label>
                        <select id="chk-province" class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 bg-white text-sm font-semibold focus:outline-none focus:ring-2 focus:ring-rose-500">
                            ${provinceOptions}
                        </select>
                    </div>

                    <div>
                        <label class="block text-xs font-bold text-slate-700 mb-1">ເມືອງ <span class="text-rose-600">*</span></label>
                        <input id="chk-district" type="text" value="${customerInfo.district}" placeholder="ເຊັ່ນ: ໄຊເສດຖາ, ຈັນທະບູລີ, ປາກເຊ..." class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 text-sm font-semibold focus:outline-none focus:ring-2 focus:ring-rose-500">
                    </div>

                    <div>
                        <label class="block text-xs font-bold text-slate-700 mb-1">ບ້ານ / ສາຂາຂົນສົ່ງທີ່ສະດວກຮັບ <span class="text-rose-600">*</span></label>
                        <input id="chk-village" type="text" value="${customerInfo.village}" placeholder="ເຊັ່ນ: ບ້ານວຽງຈະເລີນ (ຫຼື ສາຂາຂົນສົ່ງ)..." class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 text-sm font-semibold focus:outline-none focus:ring-2 focus:ring-rose-500">
                    </div>

                    <!-- Pink Note Box (Exact match to video 00:22) -->
                    <div class="p-3 rounded-xl bg-rose-50/80 border border-rose-200/80 text-xs text-rose-700 font-medium">
                        ກະລຸນາໃສ່ທີ່ຢູ່ ຫຼື ສາຂາບໍລິສັດຂົນສົ່ງຂອງທ່ານໃຫ້ຖືກຕ້ອງ.
                    </div>

                    <div>
                        <label class="block text-xs font-bold text-rose-700 mb-1">+ ເພີ່ມໝາຍເຫດ (ບໍ່ບັງຄັບ)</label>
                        <input id="chk-note" type="text" value="${customerInfo.note}" placeholder="ໝາຍເຫດເພີ່ມເຕີມ (ຖ້າມີ)..." class="w-full px-3.5 py-2 rounded-xl border border-slate-200 text-xs focus:outline-none focus:ring-2 focus:ring-rose-500">
                    </div>
                </div>

                <button onclick="goToCheckoutStep(2)" class="w-full py-3.5 px-5 rounded-xl bg-rose-600 hover:bg-rose-700 text-white text-sm sm:text-base font-extrabold shadow-md shadow-rose-600/20 transition">
                    ຕໍ່ໄປ: ບໍລິສັດຂົນສົ່ງ
                </button>

                <div class="text-center">
                    <button onclick="goToCheckoutStep(0)" class="text-xs sm:text-sm font-bold text-slate-500 hover:text-slate-800">
                        ← ກັບຄືນໄປກະຕ່າສິນຄ້າ
                    </button>
                </div>
            </div>
        `;
        return;
    }

    // ====================================================
    // STEP 2/3: ບໍລິສັດຂົນສົ່ງ (Courier Selection - Video 00:24-00:25)
    // ====================================================
    if (cartStep === 2) {
        const totalQty = getTotalCartCount();
        const subtotal = getCartSubtotal();

        const courierCardsHtml = Object.values(COURIER_OPTIONS).map(c => {
            const isSel = selectedCourier === c.id;
            const borderClass = isSel
                ? "border-2 border-rose-600 bg-rose-50/30 ring-2 ring-rose-500/20"
                : "border border-slate-200 bg-white hover:border-rose-300";

            let logoVisual = '';
            if (c.id === 'anousith') {
                logoVisual = `<div class="w-12 h-12 rounded-xl bg-white border border-slate-200 flex flex-col items-center justify-center shadow-sm">
                    <span class="text-rose-600 font-black text-base leading-none">»</span>
                    <span class="text-[7px] font-black text-slate-900 tracking-tighter mt-0.5">ANOUSITH</span>
                </div>`;
            } else if (c.id === 'mixay') {
                logoVisual = `<div class="w-12 h-12 rounded-xl bg-red-600 text-white flex flex-col items-center justify-center shadow-sm">
                    <span class="text-[9px] font-black tracking-tight">MIXAY</span>
                    <span class="text-[7px] text-amber-300 font-bold">EXPRESS</span>
                </div>`;
            } else {
                logoVisual = `<div class="w-12 h-12 rounded-xl bg-rose-700 text-white flex flex-col items-center justify-center shadow-sm">
                    <span class="text-[10px] font-black">HAL</span>
                    <span class="text-[7px] text-amber-200 font-bold">ຮຸ່ງອາລຸນ</span>
                </div>`;
            }

            return `
                <button type="button" onclick="selectCourier('${c.id}')" class="rounded-2xl p-3 flex flex-col items-center justify-center text-center gap-1.5 transition ${borderClass}">
                    ${logoVisual}
                    <div class="font-extrabold text-slate-900 text-xs sm:text-sm mt-0.5">${c.name}</div>
                    <div class="text-[11px] font-bold ${c.fee === 0 ? 'text-emerald-600' : 'text-slate-500'}">${c.feeLabel}</div>
                </button>
            `;
        }).join('');

        body.innerHTML = `
            <div class="space-y-4">
                <div>
                    <h2 class="text-lg font-extrabold text-slate-900">ດຳເນີນການສັ່ງຊື້</h2>
                    <p class="text-xs font-semibold text-slate-500 mt-0.5">ຂັ້ນຕອນ 2/3 · ບໍລິສັດຂົນສົ່ງ</p>
                    <!-- 3-Segment Progress Bar (2/3 active) -->
                    <div class="grid grid-cols-3 gap-1.5 mt-2.5">
                        <div class="h-1.5 rounded-full bg-rose-600"></div>
                        <div class="h-1.5 rounded-full bg-rose-600"></div>
                        <div class="h-1.5 rounded-full bg-slate-200"></div>
                    </div>
                </div>

                <!-- Summary Pill Bar (Video 00:24: "1 ຊິ້ນ · 299,000 ກີບ   ເບິ່ງລາຍລະອຽດ ▾") -->
                <div class="bg-white rounded-xl border border-slate-200 px-4 py-3 flex items-center justify-between text-xs sm:text-sm shadow-sm">
                    <span class="font-extrabold text-slate-800">${totalQty} ຊິ້ນ · ${formatKip(subtotal)}</span>
                    <button onclick="goToCheckoutStep(0)" class="text-rose-700 font-bold hover:underline">ເບິ່ງລາຍລະອຽດ ▾</button>
                </div>

                <!-- Courier Selection Box (Exact match to video 00:25) -->
                <div class="bg-white rounded-2xl border border-slate-200 p-4 space-y-3 shadow-sm">
                    <label class="block text-xs sm:text-sm font-extrabold text-slate-800">ບໍລິສັດຂົນສົ່ງ <span class="text-rose-600">*</span></label>
                    <div class="grid grid-cols-3 gap-2.5">
                        ${courierCardsHtml}
                    </div>
                </div>

                <button onclick="goToCheckoutStep(3)" class="w-full py-3.5 px-5 rounded-xl bg-rose-600 hover:bg-rose-700 text-white text-sm sm:text-base font-extrabold shadow-md shadow-rose-600/20 transition">
                    ຕໍ່ໄປ: ກວດ ແລະ ຢືນຢັນ
                </button>

                <div class="text-center">
                    <button onclick="goToCheckoutStep(1)" class="text-xs sm:text-sm font-bold text-slate-500 hover:text-slate-800">
                        ← ກັບຄືນ
                    </button>
                </div>

                <!-- Help Footer (Video 00:25: ຕິດຕໍ່ສອບຖາມ) -->
                <div class="pt-4 border-t border-slate-200 space-y-2 text-xs text-slate-600">
                    <div class="font-bold text-slate-800">ຕິດຕໍ່ສອບຖາມ</div>
                    <button onclick="openGeneralWhatsApp()" class="flex items-center gap-2 text-rose-700 font-semibold hover:underline">
                        <i class="fa-solid fa-box"></i>
                        <span>ຕິດຕາມການສັ່ງຊື້ / ຕິດຕໍ່ຮ້ານ (020 7889 7043)</span>
                    </button>
                </div>
            </div>
        `;
        return;
    }

    // ====================================================
    // STEP 3/3: ກວດ ແລະ ຢືນຢັນ + ສະແກນ QR BCEL One (Video 00:26-00:33)
    // ====================================================
    if (cartStep === 3) {
        const { subtotal, shippingFee, discountAmount, grandTotal, courierObj } = getOrderTotals();

        const orderLinesHtml = cartItems.map(item => `
            <div class="flex items-center justify-between text-xs sm:text-sm text-slate-700 py-1">
                <span class="truncate pr-2">${item.name} (${item.size}) × ${item.qty}</span>
                <span class="font-bold text-slate-900 shrink-0">${formatKip(item.unitPrice * item.qty)}</span>
            </div>
        `).join('');

        body.innerHTML = `
            <div class="space-y-4">
                <div>
                    <h2 class="text-lg font-extrabold text-slate-900">ດຳເນີນການສັ່ງຊື້</h2>
                    <p class="text-xs font-semibold text-slate-500 mt-0.5">ຂັ້ນຕອນ 3/3 · ກວດ ແລະ ຢືນຢັນ</p>
                    <!-- 3-Segment Progress Bar (All 3 active!) -->
                    <div class="grid grid-cols-3 gap-1.5 mt-2.5">
                        <div class="h-1.5 rounded-full bg-rose-600"></div>
                        <div class="h-1.5 rounded-full bg-rose-600"></div>
                        <div class="h-1.5 rounded-full bg-rose-600"></div>
                    </div>
                </div>

                <!-- Card 1: ສົ່ງໃຫ້ (Exact match to video 00:26-00:29) -->
                <div class="bg-white rounded-2xl border border-slate-200 p-4 space-y-3 shadow-sm">
                    <h3 class="text-sm font-extrabold text-slate-900">ສົ່ງໃຫ້</h3>
                    <div class="flex items-start justify-between gap-2 text-xs sm:text-sm">
                        <div>
                            <div class="font-extrabold text-slate-900">${customerInfo.name} · ${customerInfo.phone}</div>
                            <div class="text-slate-500 mt-0.5">${customerInfo.village}, ${customerInfo.district}, ${customerInfo.province}</div>
                            ${customerInfo.note ? `<div class="text-slate-400 text-xs mt-0.5">ໝາຍເຫດ: ${customerInfo.note}</div>` : ''}
                        </div>
                        <button onclick="goToCheckoutStep(1)" class="text-rose-700 font-bold text-xs hover:underline shrink-0">ແກ້ໄຂ</button>
                    </div>
                    <div class="pt-2.5 border-t border-slate-100 flex items-center justify-between text-xs sm:text-sm">
                        <div class="flex items-center gap-2 font-bold text-slate-800">
                            <span>🚚</span>
                            <span>${courierObj.name} · ${courierObj.feeLabel}</span>
                        </div>
                        <button onclick="goToCheckoutStep(2)" class="text-rose-700 font-bold text-xs hover:underline">ແກ້ໄຂ</button>
                    </div>
                </div>

                <!-- Card 2: ສະຫຼຸບການສັ່ງຊື້ (Exact match to video 00:27-00:30) -->
                <div class="bg-white rounded-2xl border border-slate-200 p-4 space-y-2.5 shadow-sm">
                    <h3 class="text-sm font-extrabold text-slate-900">ສະຫຼຸບການສັ່ງຊື້</h3>
                    <div class="divide-y divide-slate-100">
                        ${orderLinesHtml}
                    </div>
                    <div class="pt-2 border-t border-slate-100 space-y-1.5 text-xs sm:text-sm">
                        <div class="flex items-center justify-between text-slate-600">
                            <span>ລາຄາສິນຄ້າ</span>
                            <span class="font-semibold text-slate-900">${formatKip(subtotal)}</span>
                        </div>
                        <div class="flex items-center justify-between text-slate-600">
                            <span>ຄ່າແພັກ</span>
                            <span class="font-extrabold text-emerald-600">ຟຣີ</span>
                        </div>
                        ${shippingFee > 0 ? `
                        <div class="flex items-center justify-between text-slate-600">
                            <span>ຄ່າຂົນສົ່ງ (${courierObj.name})</span>
                            <span class="font-semibold text-slate-900">${formatKip(shippingFee)}</span>
                        </div>` : ''}
                        ${discountAmount > 0 ? `
                        <div class="flex items-center justify-between text-emerald-700 font-bold">
                            <span>ສ່ວນຫຼຸດ (${appliedCoupon} -5%)</span>
                            <span>-${formatKip(discountAmount)}</span>
                        </div>` : ''}
                    </div>
                    <div class="pt-2.5 border-t border-slate-200 flex items-center justify-between">
                        <span class="text-sm sm:text-base font-extrabold text-slate-900">ລວມທັງໝົດ</span>
                        <span class="text-lg sm:text-xl font-extrabold text-rose-700">${formatKip(grandTotal)}</span>
                    </div>
                </div>

                <!-- Card 3: ລະຫັດສ່ວນຫຼຸດ (Exact match to video 00:30-00:33) -->
                <div class="bg-white rounded-2xl border border-slate-200 p-4 space-y-2.5 shadow-sm">
                    <div class="flex items-center justify-between">
                        <h3 class="text-sm font-extrabold text-slate-900">ລະຫັດສ່ວນຫຼຸດ</h3>
                        <button type="button" onclick="document.getElementById('chk-coupon-input').value='NEW5'; applyDiscountCoupon();" class="text-[11px] font-bold text-rose-600 hover:underline">
                            🎁 ກົດໃຊ້ລະຫັດລູກຄ້າໃໝ່ NEW5 (-5%)
                        </button>
                    </div>
                    <div class="flex gap-2">
                        <input id="chk-coupon-input" type="text" value="${appliedCoupon || ''}" placeholder="ໃສ່ລະຫັດສ່ວນຫຼຸດ (ເຊັ່ນ: NEW5)" class="flex-grow px-3.5 py-2.5 rounded-xl border border-slate-200 text-xs sm:text-sm font-bold uppercase focus:outline-none focus:ring-2 focus:ring-rose-500">
                        <button type="button" onclick="applyDiscountCoupon()" class="px-5 py-2.5 rounded-xl bg-rose-700 hover:bg-rose-800 text-white text-xs sm:text-sm font-extrabold shrink-0 transition">
                            ນຳໃຊ້
                        </button>
                    </div>
                </div>

                <!-- Card 4: ສະແກນ QR ເພື່ອຊຳລະເງິນ (BCEL One) (Exact match to video 00:29-00:33) -->
                <div class="bg-white rounded-2xl border border-slate-200 p-4 space-y-3 shadow-sm">
                    <h3 class="text-sm font-extrabold text-slate-900">ສະແກນ QR ເພື່ອຊຳລະເງິນ</h3>
                    <p class="text-xs text-rose-700 font-semibold leading-relaxed">
                        ກະລຸນາສະແກນ QR ດ້ວຍແອັບ <strong>BCEL One</strong> ແລ້ວໂອນເງິນຕາມຍອດລວມຂ້າງລຸ່ມ (<strong>${formatKip(grandTotal)}</strong>). ຢ່າລືມຖ່າຍຮູບໃບໂອນເງິນໄວ້.
                    </p>

                    <!-- BCEL OnePay Styled QR Box -->
                    <div class="max-w-xs mx-auto rounded-2xl border-2 border-red-600 bg-white overflow-hidden shadow-md text-center">
                        <div class="bg-red-600 text-white py-2 px-3 flex items-center justify-center gap-2 font-extrabold text-xs">
                            <i class="fa-solid fa-qrcode"></i>
                            <span>BCEL OnePay • ນິຍົມ ການກະເສດ</span>
                        </div>
                        <div class="p-4 flex flex-col items-center">
                            <img src="https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=${encodeURIComponent(`BCEL_ONEPAY|SHOP:NIYOM_VET|TEL:${SHOP_PHONE_DISPLAY}|AMOUNT:${grandTotal}_LAK`)}" alt="BCEL One QR" class="w-44 h-44 object-contain rounded-lg border border-slate-200 p-1.5">
                            <div class="mt-2.5 text-xs font-bold text-slate-800">ຮ້ານ ນິຍົມ ການກະເສດ (${SHOP_PHONE_DISPLAY})</div>
                            <div class="text-sm font-extrabold text-rose-600 mt-0.5">ຍອດຊຳລະ: ${formatKip(grandTotal)}</div>
                        </div>
                    </div>

                    <!-- Optional Slip Upload -->
                    <div class="pt-2">
                        <label class="cursor-pointer w-full py-2.5 px-4 rounded-xl border-2 border-dashed border-rose-300 bg-rose-50/50 hover:bg-rose-50 text-rose-700 text-xs font-extrabold flex items-center justify-center gap-2 transition">
                            <i class="fa-solid fa-camera"></i>
                            <span>${uploadedSlipDataUrl ? '✅ ແນບຮູບໃບໂອນເງິນແລ້ວ (ກົດເພື່ອປ່ຽນຮູບ)' : 'ກົດແນບຮູບໃບໂອນເງິນ (ສະລິບ BCEL One)'}</span>
                            <input type="file" accept="image/*" class="hidden" onchange="handleSlipUpload(event)">
                        </label>
                        ${uploadedSlipDataUrl ? `<img src="${uploadedSlipDataUrl}" class="mt-2 max-h-36 mx-auto rounded-xl border border-slate-200 shadow-sm object-contain">` : ''}
                    </div>
                </div>

                <!-- Final Confirm Order Button -->
                <button onclick="submitLaocartOrder()" class="w-full py-4 px-5 rounded-xl bg-rose-600 hover:bg-rose-700 active:scale-[0.99] text-white text-sm sm:text-base font-extrabold shadow-lg shadow-rose-600/25 flex items-center justify-center gap-2 transition">
                    <i class="fa-solid fa-circle-check"></i>
                    <span>ຢືນຢັນການສັ່ງຊື້ (${formatKip(grandTotal)})</span>
                </button>

                <div class="text-center">
                    <button onclick="goToCheckoutStep(2)" class="text-xs sm:text-sm font-bold text-slate-500 hover:text-slate-800">
                        ← ກັບຄືນ
                    </button>
                </div>
            </div>
        `;
        return;
    }

    // ====================================================
    // STEP 4: ສັ່ງຊື້ສຳເລັດ! (Order Completed Screen - Video 00:32)
    // ====================================================
    if (cartStep === 4 && lastCompletedOrder) {
        const o = lastCompletedOrder;
        body.innerHTML = `
            <div class="space-y-4 text-center py-2">
                <!-- Yellow Banner from Video 00:32: "ຊຳລະແລ້ວ ລໍຖ້າຮັບບິນເຄື່ອງເລີຍ 1-2 ມື້" -->
                <div class="inline-block px-5 py-2.5 rounded-2xl bg-amber-300 text-slate-950 font-extrabold text-sm sm:text-base shadow-md">
                    🎉 ສັ່ງຊື້ສຳເລັດ! ລໍຖ້າຮັບບິນເຄື່ອງເລີຍ 1–2 ມື້
                </div>

                <div class="bg-white rounded-2xl border border-slate-200 p-4 text-left space-y-3 shadow-sm">
                    <div class="flex items-center justify-between border-b border-slate-100 pb-2.5">
                        <div>
                            <span class="text-[11px] font-bold text-slate-400">ລະຫັດຄຳສັ່ງຊື້</span>
                            <h4 class="font-extrabold text-slate-900 text-base">#${o.orderId}</h4>
                        </div>
                        <span class="px-2.5 py-1 rounded-full bg-emerald-50 text-emerald-700 border border-emerald-200 text-xs font-extrabold">
                            <i class="fa-solid fa-check mr-1"></i>ບັນທຶກບິນແລ້ວ
                        </span>
                    </div>

                    <div class="text-xs space-y-1 text-slate-600">
                        <div><strong>ຜູ້ຮັບ:</strong> ${o.customer.name} (${o.customer.phone})</div>
                        <div><strong>ທີ່ຢູ່ຈັດສົ່ງ:</strong> ${o.customer.village}, ${o.customer.district}, ${o.customer.province}</div>
                        <div><strong>ບໍລິສັດຂົນສົ່ງ:</strong> ${o.courier.fullName}</div>
                    </div>

                    <div class="pt-2 border-t border-slate-100 space-y-1 text-xs">
                        ${o.items.map(i => `
                            <div class="flex justify-between text-slate-700">
                                <span>${i.name} (${i.size}) × ${i.qty}</span>
                                <span class="font-bold">${formatKip(i.unitPrice * i.qty)}</span>
                            </div>
                        `).join('')}
                        <div class="pt-2 border-t border-slate-100 flex justify-between text-sm font-extrabold text-rose-700">
                            <span>ຍອດລວມທັງໝົດ</span>
                            <span>${formatKip(o.grandTotal)}</span>
                        </div>
                    </div>
                </div>

                <button onclick="sendOrderBillWhatsApp()" class="w-full py-3.5 px-5 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white text-xs sm:text-sm font-extrabold shadow-md flex items-center justify-center gap-2 transition">
                    <i class="fa-brands fa-whatsapp text-lg"></i>
                    <span>ສົ່ງບິນຄຳສັ່ງຊື້ & ຮູບສະລິບເຂົ້າ WhatsApp ຮ້ານທັນທີ</span>
                </button>

                <button onclick="closeCartModal()" class="w-full py-2.5 px-4 rounded-xl bg-slate-200 hover:bg-slate-300 text-slate-800 text-xs font-bold transition">
                    ກັບໄປໜ້າຮ້ານ
                </button>
            </div>
        `;
    }
}

// Image Lightbox Functions
function openImageLightbox(src, caption) {
    if (!src) return;
    const modal = document.getElementById('image-modal');
    document.getElementById('lightbox-img').src = src;
    document.getElementById('lightbox-caption').innerText = caption || '';
    modal.classList.remove('hidden');
}

function openImageFromDetail() {
    const drugId = document.getElementById('detail-modal').dataset.activeDrugId;
    const drug = DRUGS_DATA.find(d => d.id === drugId);
    if (drug && drug.image) {
        openImageLightbox(drug.image, drug.name);
    }
}

function closeImageLightbox() {
    document.getElementById('image-modal').classList.add('hidden');
}

// Calculator Handling
function populateCalculatorDropdown() {
    const select = document.getElementById('calc-drug-select');
    if (!select) return;
    select.innerHTML = '';
    DRUGS_DATA.forEach(d => {
        const opt = document.createElement('option');
        opt.value = d.id;
        opt.text = `${d.name} (${d.active.split('+')[0].trim()})`;
        select.appendChild(opt);
    });
}

function openCalculator(preselectDrugId) {
    const modal = document.getElementById('calc-modal');
    if (preselectDrugId) {
        document.getElementById('calc-drug-select').value = preselectDrugId;
    }
    calculateDosage();
    modal.classList.remove('hidden');
}

function closeCalculator() {
    document.getElementById('calc-modal').classList.add('hidden');
}

function calculateDosage() {
    const drugId = document.getElementById('calc-drug-select').value;
    const weight = parseFloat(document.getElementById('calc-weight').value) || 0;
    const species = document.getElementById('calc-species').value;
    const drug = DRUGS_DATA.find(d => d.id === drugId);

    if (!drug) return;

    let result = 0;
    let route = "IM (ກ້າມຊີ້ນ)";
    let specialWarn = "";

    switch (drug.id) {
        case 'ivermec-f':
            result = weight * (1 / 60);
            route = "SC (ໃຕ້ຜິວໜັງເທົ່ານັ້ນ! ຫ້າມ IV/IM)";
            if (species === 'pet') {
                specialWarn = "ຄຳເຕືອນ: ບໍ່ແນະນຳໃຫ້ໃຊ້ Ivermec-F ກັບໝາ ເພາະເຂັ້ມຂຸ້ນສູງຫຼາຍ ແລະ ອາດຕາຍທັນທີຫາກເປັນພັນຄໍລີ!";
            }
            break;
        case 'vimec-ivermectin':
            result = weight / 50;
            route = "SC (ສັກເຂົ້າໃຕ້ຜິວໜັງເທົ່ານັ້ນ)";
            break;
        case 'butasyl':
            result = weight >= 150 ? 10 : 5;
            route = "Slow IV (ເສັ້ນເລືອດດຳຊ້າໆເທົ່ານັ້ນ! ຫ້າມສັກກ້າມຊີ້ນ IM)";
            specialWarn = "ຄຳເຕືອນອັນຕະລາຍ: Butasyl ຕ້ອງສັກເຂົ້າຫຼອດເລືອດດຳ Slow IV ເທົ່ານັ້ນ ຫ້າມສັກກ້າມຊີ້ນ IM ເດັດຂາດ";
            break;
        case 'oxytocin':
            if (species === 'cattle') result = 3.5;
            else if (species === 'pig') result = 2.0;
            else if (species === 'poultry') result = 0.08;
            else result = 0.5;
            route = "IM (ສັກກ້າມຊີ້ນ)";
            specialWarn = "ໝາຍເຫດ: ໃຊ້ສຳລັບເລັ່ງເກີດ (ປາກມົດລູກເປີດແລ້ວ) ຫຼື ຂັບຮົກພາຍໃນ 2–6 ຊົ່ວໂມງຫຼັງເກີດ";
            break;
        case 'berenil':
            result = weight / 20;
            route = "Deep IM (ກ້າມຊີ້ນເລິກ)";
            specialWarn = "ສຳຄັນທີ່ສຸດ: ສັກພຽງ ຄັ້ງດຽວ (1 ເຂັມ) ເທົ່ານັ້ນ! ຫ້າມສັກຊ້ຳທຸກມື້";
            break;
        case 'octacin-n':
            result = weight * 0.15;
            route = "Deep IM / SC";
            break;
        case 'diclofenac-plus':
            result = weight / 25;
            route = "IM (ກ້າມຊີ້ນ)";
            break;
        case 'kanamycin':
            result = weight / 30;
            route = "IM / SC";
            break;
        case 'gental-vet':
            if (species === 'cattle') result = weight / 40;
            else if (species === 'pig') result = weight / 20;
            else result = weight / 10;
            route = "IM (ກ້າມຊີ້ນ)";
            break;
        case 'vitadex-b12':
            if (species === 'cattle') result = Math.min(40, Math.max(20, weight * 0.08));
            else if (species === 'pig') result = Math.min(30, Math.max(10, weight * 0.2));
            else result = 5;
            route = "SC / Slow IV";
            break;
        case 'ad3e-500':
            if (species === 'poultry') result = 0.15;
            else result = weight * 0.02;
            route = "IM (ກ້າມຊີ້ນເອິກ) / SC";
            break;
        case 'amoxy-la':
        case 'bio-amox-la':
            result = weight / 10;
            route = "IM (ກ້າມຊີ້ນ - ອອກລິດຍາວ 48 ຊມ. ສັກວັນເວັ້ນວັນ)";
            specialWarn = "ປອດໄພສູງສຸດໃນສັດຖືພາ: ສັ່ນຂວດໃຫ້ດີກ່ອນດູດຢາ ຫ້າມສັກເຂົ້າເສັ້ນເລືອດດຳ (IV)";
            break;
        case 'ketoprofen':
            result = weight / 33;
            route = "IM / Slow IV (ວັນລະ 1 ຄັ້ງ)";
            specialWarn = "ປອດໄພໃນສັດຖືພາ: ເປັນຢາຫຼຸດໄຂ້-ແກ້ປວດທາງເລືອກທຳອິດສຳລັບແມ່ພັນຖືພາ";
            break;
        case 'catosal':
            if (species === 'cattle') result = Math.min(25, Math.max(10, weight / 20));
            else if (species === 'poultry') result = 0.3;
            else result = Math.min(10, Math.max(2, weight / 10));
            route = "IM / SC / IV";
            break;
        case 'calcium-borogluconate':
            result = weight * 0.8;
            route = "Slow IV (ເຂົ້າເສັ້ນເລືອດຊ້າໆທີ່ສຸດ) ຫຼື ແບ່ງສັກ SC ຫຼາຍຈຸດ";
            specialWarn = "ຄຳເຕືອນອັນຕະລາຍ: ຖ້າໃຫ້ທາງເສັ້ນເລືອດ (IV) ຕ້ອງປ່ອຍຢາຊ້າໆທີ່ສຸດ! ຖ້າໄວເກີນໄປຫົວໃຈສັດຈະຢຸດເຕັ້ນທັນທີ";
            break;
        case 'sulfa-tmp':
            result = weight / 15;
            route = "IM (ກ້າມຊີ້ນ)";
            break;
        case 'albendazole-oral':
            result = weight / 12;
            route = "Oral (ຢານ້ຳກອກປາກເທົ່ານັ້ນ! ຫ້າມສັກ)";
            specialWarn = "ຫ້າມໃຊ້ໃນສັດຖືພາໄລຍະທ້ອງອ່ອນ (45 ມື້ທຳອິດ) ເດັດຂາດ ເພາະຈະເຮັດໃຫ້ລູກພິການ ຫຼື ແທ້ງ!";
            break;
        default:
            if (drug.calcRate === 0) {
                result = 0;
                route = currentLang === 'lo' ? drug.ratioText_lo : drug.ratioText_th;
                specialWarn = "ໝາຍເຫດ: ຢານີ້ເປັນຢາໃຊ້ພາຍນອກ, ຢາຢອດ ຫຼື ຢາປ້ອນເປັນເມັດ (ກະລຸນາເບິ່ງອັດຕາສ່ວນມາດຕະຖານຂ້າງເທິງ)";
            } else {
                result = weight * drug.calcRate;
                route = "IM / SC";
            }
    }

    document.getElementById('calc-result').innerText = result.toFixed(2);
    document.getElementById('calc-standard-rate').innerText = currentLang === 'lo' ? drug.ratioText_lo : drug.ratioText_th;
    document.getElementById('calc-route-text').innerText = route;

    const warnBox = document.getElementById('calc-special-warning');
    if (specialWarn) {
        warnBox.innerText = specialWarn;
        warnBox.classList.remove('hidden');
    } else {
        warnBox.classList.add('hidden');
    }
}
